import {b,a,f,s,c} from '../authoring.js';

// Values describe a small teaching database; scenes are explanatory, not live output.
const client = (lines=[]) => a('app','client','Приложение','Application',lines);
const backend = (lines=[]) => a('db','server','Postgres','Postgres',lines);
const orders = (rows=[],lines=[]) => a('orders','table','Заказы','Orders',lines,{columns:['id','customer_id','item','qty'],rows});
const firstOrders = (lines=[]) => a('orders','table','Заказы','Orders',lines,{columns:['id','item','qty'],rows:[[17,'Book',1]]});
const accounts = (rows,lines=[]) => a('accounts','table','Счета','Accounts',lines,{columns:['id','balance'],rows});
const wal = (items,lines=[]) => a('wal','wal','Журнал WAL','WAL log',lines,{items});
const status = (key,ru,en,lines=[]) => a(key,'status',ru,en,lines);
const versions = (rows,lines=[]) => a('heap','page','Версии на странице','Versions on a page',lines,{columns:['tuple','xmin','xmax','value'],rows});

export const chapters = [
  c({number:1,id:'first-order',group:0,title:['Сохранить первый заказ','Save the first order'],question:['Приложение приняло заказ. Как сохранить его и прочитать обратно?','The app accepted an order. How can it save and read it back?'],next:['Заказ вернулся. Почему данные организованы в строки и столбцы?','The order came back. Why organize data into rows and columns?'],docs:['tutorial-populate.html','tutorial-select.html','tutorial-transactions.html'],book:[41,43],steps:[
    s('Покупатель оформил заказ №17. Пока он существует только в приложении.','A customer placed order 17. For now, it exists only in the app.',[client([b('Заказ 17','Order 17'),'Book × 1',b('Ещё не сохранён','Not saved yet')])],[],'','Приложению нужно сохранить три значения: номер 17, товар Book и количество 1. После закрытия окна эти данные должны оставаться доступными.','The app needs to save three values: ID 17, item Book, and quantity 1. They must remain available after the window closes.'),
    s('Приложение отправляет INSERT по соединению с сервером.','The app sends INSERT over its connection to the server.',[client(['17 · Book · 1']),backend([b('Получен INSERT','INSERT received')])],[f('app','db','INSERT')],"INSERT INTO orders (id, item, qty) VALUES (17, 'Book', 1);",'SQL описывает требуемое изменение. Обслуживающий процесс Postgres получает команду по соединению; приложение не открывает файлы таблицы самостоятельно.','SQL describes the requested change. A Postgres backend receives the command through the connection; the app does not open table files itself.'),
    s('Сервер добавляет строку в неявной транзакции. Ответ об успехе ещё не отправлен.','The server inserts the row in an implicit transaction. It has not replied with success yet.',[client([b('Ожидает ответ','Waiting for a reply')]),backend([b('Транзакция открыта','Transaction open')]),firstOrders([b('Изменение в работе','Change in progress')])],[f('db','orders','INSERT','internal')],'','Без явного BEGIN отдельная команда всё равно выполняется в транзакции. На этом шаге показываем логическую строку; её физическое устройство разберём позже.','Even without an explicit BEGIN, a standalone command runs in a transaction. This scene shows the logical row; its physical representation comes later.'),
    s('Неявная транзакция фиксируется, и только затем приложение получает успешный ответ.','The implicit transaction commits before the app receives a successful reply.',[client([b('Заказ принят','Order accepted')]),backend(['COMMIT ✓']),firstOrders([b('Зафиксировано','Committed')])],[f('db','app','INSERT 0 1','reply')],'','При обычном режиме надёжной фиксации подтверждение INSERT приходит после завершения неявного COMMIT и необходимого сохранения WAL. Мы ещё откроем этот механизм, но сохранение уже работает.','With normal durable commit settings, INSERT success follows the implicit COMMIT and the required WAL flush. We will open that mechanism later; persistence is already part of this operation.'),
    s('Следующий запрос просит вернуть сохранённый заказ.','The next query asks for the saved order.',[client(['id = 17']),backend(['SELECT']),firstOrders()],[f('app','db','SELECT'),f('db','orders','id = 17','internal')],"SELECT id, item, qty FROM orders WHERE id = 17;",'Новый SQL-запрос обращается к таблице на сервере. Он может прийти по тому же соединению или из другого сеанса после фиксации вставки.','A new SQL query reads the server table. It can use the same connection or another session after the insertion commits.'),
    s('Приложение получает ровно те значения, которые сохранило: 17, Book, 1.','The app receives exactly the saved values: 17, Book, 1.',[client(['17 · Book · 1',b('Прочитано с сервера','Read from the server')]),backend(),firstOrders()],[f('orders','db',b('Одна строка','One row'),'internal'),f('db','app',b('Одна строка','One row'),'reply')],'','Запись и чтение образуют первый проверяемый круг: команда, изменение, фиксация, ответ, новый запрос и результат. Теперь разберём, какую структуру сервер придал данным.','Write and read complete the first observable cycle: command, change, commit, reply, new query, result. Next we examine the structure the server gives these values.')
  ]}),
  c({number:2,id:'tables',group:0,title:['Строки, типы и ограничения','Rows, types, and constraints'],question:['Как хранить много заказов так, чтобы их смысл не терялся?','How can many orders keep a consistent meaning?'],next:['Один заказ сохранён. А если одно действие должно изменить сразу две строки?','One order is saved. What if one action must change two rows?'],docs:['ddl-basics.html','ddl-constraints.html','datatype.html'],book:[23,33],steps:[
    s('У каждого заказа повторяются одни и те же поля.','Every order repeats the same fields.',[orders([[17,42,'Book',1],[18,8,'Pen',2]])],[],'','Строка описывает один заказ, а столбец — одно свойство. В учебной таблице customer_id связывает заказ с покупателем; название столбца сохраняет смысл значения 42.','A row describes one order, and a column describes one property. In this teaching table, customer_id identifies the customer; the column name gives the value 42 its meaning.'),
    s('Схема объявляет, какие значения допустимы в каждом столбце.','The schema declares which values each column accepts.',[a('schema','table','Схема orders','orders schema',[],{columns:['column','type','rule'],rows:[['id','integer','PRIMARY KEY'],['customer_id','integer','DEFAULT 42'],['item','text','NOT NULL'],['qty','integer','CHECK > 0']]})],[],"CREATE TABLE orders (\n  id integer PRIMARY KEY,\n  customer_id integer NOT NULL DEFAULT 42,\n  item text NOT NULL,\n  qty integer NOT NULL CHECK (qty > 0)\n);",'Это полное определение учебной таблицы, уже использованной в первой сцене. DEFAULT подставляет customer_id=42, когда INSERT его пропускает; тип integer проверяет представление числа.','This is the full definition of the teaching table used in the first scene. DEFAULT supplies customer_id=42 when INSERT omits it; integer validates the numeric representation.'),
    s('Количество «many» нельзя представить как integer: строка не добавляется.','The value “many” is not an integer, so the row is not inserted.',[client(["qty = 'many'"]),backend(['invalid input syntax']),orders([[17,42,'Book',1],[18,8,'Pen',2]])],[f('app','db','INSERT'),f('db','app','ERROR','reply')],"INSERT INTO orders (id, item, qty) VALUES (19, 'Pen', 'many');",'Команда завершается ошибкой преобразования типа. Сервер не сохраняет частично заполненную строку с неправильным количеством; существующие заказы остаются прежними.','The command fails during type conversion. The server does not store a partially filled row with an invalid quantity; existing orders remain unchanged.'),
    s('Ограничения отсекают повторный номер и неположительное количество.','Constraints reject a duplicate ID and a nonpositive quantity.',[a('rules','status','Правила таблицы','Table rules',['id: unique + not null','qty > 0']),orders([[17,42,'Book',1],[18,8,'Pen',2]])],[f('rules','orders',b('Защищают запись','Guard writes'),'internal')],"INSERT INTO orders (id, item, qty) VALUES (17, 'Pencil', 1);\n-- Separate attempt:\nINSERT INTO orders (id, item, qty) VALUES (19, 'Pencil', 0);",'Это две отдельные неудачные попытки: первая нарушает PRIMARY KEY, вторая CHECK. Первичный ключ также создаёт уникальный индекс; к работе индексов мы вернёмся на запросе поиска.','These are two separate failed attempts: one violates the PRIMARY KEY, the other the CHECK. The primary key also creates a unique index; we return to indexes when a lookup needs one.'),
    s('Теперь новый заказ проходит все проверки и становится обычной строкой.','A valid new order passes all checks and becomes another row.',[client(['19 · Pencil · 3']),orders([[17,42,'Book',1],[18,8,'Pen',2],[19,42,'Pencil',3]])],[f('app','orders','INSERT','request')],"INSERT INTO orders (id, item, qty)\nVALUES (19, 'Pencil', 3) RETURNING *;",'Схема защищает значения каждой строки. Но действие вроде перевода денег требует общего правила для нескольких изменений: либо применить все, либо не применить ни одного.','The schema protects values in each row. An action such as a money transfer needs a rule across several changes: apply all of them or none of them.')
  ]}),
  c({number:3,id:'transactions',group:0,title:['Одно действие — несколько изменений','One action, several changes'],question:['Как перевести 30 так, чтобы деньги не исчезли между двумя UPDATE?','How can a transfer of 30 avoid losing money between two UPDATEs?'],next:['Изменения объединены. Как быстро найти нужный заказ среди многих?','Changes are grouped. How can we find one customer’s orders quickly?'],docs:['tutorial-transactions.html','sql-begin.html','sql-rollback.html'],book:[47,54],steps:[
    s('На счетах 100 и 50. Перевод 30 должен сохранить общую сумму 150.','The balances are 100 and 50. A transfer of 30 must preserve their total of 150.',[accounts([['A',100],['B',50]],['total = 150'])],[],"CREATE TABLE accounts (id text PRIMARY KEY, balance integer NOT NULL);\nINSERT INTO accounts VALUES ('A', 100), ('B', 50);",'Две строки представляют одно бизнес-действие. Недостаточно успешно выполнить списание: зачисление должно завершиться вместе с ним.','Two rows participate in one business action. A successful debit is insufficient: the credit must complete together with it.'),
    s('BEGIN открывает группу изменений; первое UPDATE списывает 30 со счёта A.','BEGIN opens the change group; the first UPDATE debits 30 from A.',[client(['transfer = 30']),backend(['BEGIN','UPDATE A']),accounts([['A',70],['B',50]],[b('Свои изменения','Own changes')])],[f('app','db','BEGIN'),f('db','accounts','A: 100 → 70','internal')],"BEGIN;\nUPDATE accounts SET balance = balance - 30 WHERE id = 'A';",'Внутри транзакции её собственные запросы уже могут видеть A=70. Эта промежуточная картина ещё не является зафиксированным результатом перевода для других сеансов.','The transaction can already see its own A=70. This intermediate state is not yet the transfer’s committed result for other sessions.'),
    s('Второе UPDATE зачисляет те же 30 на счёт B.','The second UPDATE credits the same 30 to B.',[backend(['transaction open']),accounts([['A',70],['B',80]],['total = 150'])],[f('db','accounts','B: 50 → 80','internal')],"UPDATE accounts SET balance = balance + 30 WHERE id = 'B';",'Оба изменения пока принадлежат одной открытой транзакции. Приложение не должно объявлять перевод завершённым до успешной фиксации всей группы.','Both changes still belong to one open transaction. The app must not declare the transfer complete before the whole group successfully commits.'),
    s('COMMIT фиксирует оба изменения как один завершённый перевод.','COMMIT commits both changes as one completed transfer.',[client([b('Перевод завершён','Transfer complete')]),backend(['COMMIT ✓']),accounts([['A',70],['B',80]],['total = 150'])],[f('db','app','COMMIT','reply')],'COMMIT;','Другой сеанс с новым снимком после фиксации увидит результат целиком: A=70 и B=80. Устройство снимков позднее уточнит, когда именно читатель получает эту картину.','Another session taking a fresh snapshot after commit sees the complete result: A=70 and B=80. Later, snapshots explain exactly when a reader obtains that view.'),
    s('В альтернативном запуске после списания приложение обнаруживает ошибку.','In an alternative run, the app detects a problem after the debit.',[client([b('Зачисление невозможно','Credit cannot proceed')]),backend(['BEGIN','A: 100 → 70']),accounts([['A',70],['B',50]],[b('Незафиксировано','Uncommitted')])],[],"-- Alternative run from A=100, B=50:\nBEGIN;\nUPDATE accounts SET balance = balance - 30 WHERE id = 'A';",'Это отдельная ветка примера из начальных 100 и 50. До COMMIT приложение может отменить перевод; при SQL-ошибке обычная транзакция также требует отката перед продолжением.','This is an alternative branch starting at 100 and 50. Before COMMIT the app can cancel the transfer; after a SQL error, an ordinary transaction also requires rollback before continuing.'),
    s('ROLLBACK отменяет результат группы: для новых чтений снова 100 и 50.','ROLLBACK cancels the group’s result: new reads again see 100 and 50.',[backend(['ROLLBACK']),accounts([['A',100],['B',50]],['total = 150']),client([b('Перевод отменён','Transfer canceled')])],[f('db','accounts',b('Не публиковать изменения','Discard logical changes'),'internal'),f('db','app','ROLLBACK','reply')],'ROLLBACK;','Здесь показан логический результат отката. Это не обещание, что сервер немедленно переписал старые байты на место: многоверсионность позднее объяснит физические следы отменённых изменений.','This is the logical result of rollback. It does not imply that the server immediately restored old bytes in place: MVCC will later explain the physical remnants of aborted changes.')
  ]}),
  c({number:4,id:'first-index',group:0,title:['Найти заказы покупателя','Find a customer’s orders'],question:['Почему поиск customer_id=42 начинает делать слишком много работы?','Why does searching customer_id=42 begin to do too much work?'],next:['Индекс нашёл адрес. Что именно находится по этому адресу?','The index found an address. What is stored there?'],docs:['indexes-intro.html','indexes-types.html','using-explain.html'],book:[89,90],steps:[
    s('Запросу нужны заказы покупателя 42, а не все заказы магазина.','The query needs customer 42’s orders, not every order in the store.',[orders([[3,8,'Pen',1],[9,15,'Cup',2],[17,42,'Book',1],[26,8,'Bag',1],[19,42,'Pencil',3]])],[],"SELECT id, item FROM orders WHERE customer_id = 42;",'Первичный ключ ускоряет поиск по id, но не обязан помогать условию по customer_id. В маленькой таблице перебрать все строки дёшево.','The primary key supports lookup by id, but need not help a condition on customer_id. Scanning every row in a small table is cheap.'),
    s('Таблица выросла до 100 000 строк. Полный просмотр всё ещё проверяет каждую.','The table grows to 100,000 rows. A full scan still checks every row.',[a('scan','timeline','Полный просмотр','Full scan',[],{items:['1…20000','20001…40000','40001…60000','60001…80000','80001…100000']}),status('result','Совпадения','Matches',['id 17','id 19'])],[f('scan','result','customer_id = 42','internal')],'','В примере подходят только два заказа, однако путь без подходящего индекса проверяет условие у всей таблицы. Число прочитанных страниц становится важнее числа возвращённых строк.','Only two orders match in this example, yet a path without a suitable index checks the whole table. Pages examined can matter more than rows returned.'),
    s('B-tree связывает упорядоченный ключ customer_id с адресами строк.','A B-tree maps ordered customer_id keys to row locations.',[a('index','tree','Индекс покупателя','Customer index',[],{nodes:[{id:'root',label:'< 20 | < 60 | >= 60'},{id:'left',label:'8, 15'},{id:'middle',label:'42 → (4,2), (9,1)'},{id:'right',label:'73, 91'}],edges:[['root','left'],['root','middle'],['root','right']]})],[],"CREATE INDEX orders_customer_idx ON orders (customer_id);",'У внутренней страницы B-tree может быть много потомков: это не бинарное дерево. Лист хранит ключ и ссылки на версии строк; обозначения (4,2) и (9,1) пока считайте адресами.','A B-tree internal page can have many children; it is not a binary tree. A leaf holds a key and references to row versions; treat (4,2) and (9,1) as locations for now.'),
    s('Поиск ключа 42 ведёт к двум адресам вместо проверки всех строк.','Looking up key 42 leads to two locations instead of testing every row.',[a('index','tree','Путь ключа 42','Path for key 42',[],{nodes:[{id:'root',label:'20 ≤ 42 < 60'},{id:'leaf',label:'42 → (4,2), (9,1)'}],edges:[['root','leaf']]}),orders([[17,42,'Book',1],[19,42,'Pencil',3]])],[f('index','orders','(4,2), (9,1)','internal')],"SELECT id, item FROM orders WHERE customer_id = 42;",'После поиска индексных записей обычный index scan обращается к самой таблице. Индекс не содержит автоматически все столбцы и все сведения о видимости строки.','After finding index entries, an ordinary index scan visits the table itself. An index does not automatically contain every column or all tuple visibility information.'),
    s('Подходящий индекс добавляет короткий путь; планировщик решает, выгоден ли он.','A suitable index adds a shortcut; the planner decides whether it is worthwhile.',[status('choice','Выбор пути','Path choice',[b('Мало совпадений: индекс','Few matches: index'),b('Много: возможен scan','Many: scan may win')]),orders([[17,42,'Book',1],[19,42,'Pencil',3]])],[f('choice','orders',b('Тот же результат','Same result'),'internal')],'','Индекс требует места и обслуживания при записи. При большом числе совпадений полный просмотр может оказаться дешевле. Сначала откроем адрес таблицы, к которому привёл выбранный путь.','An index takes storage and maintenance on writes. With many matches, a full scan can be cheaper. First, we open the table location reached by the chosen path.')
  ]}),
  c({number:5,id:'pages',group:0,title:['Адрес внутри страницы','A location inside a page'],question:['Что означает адрес версии (4,2), полученный из индекса?','What does the row-version location (4,2) mean?'],next:['Страницу нашли в файле. Откуда её читает работающий запрос?','We located the page in a file. Where does a running query read it?'],docs:['storage-file-layout.html','storage-page-layout.html','ddl-system-columns.html'],book:[75,80],steps:[
    s('Файл таблицы состоит из страниц фиксированного размера.','A table file consists of fixed-size pages.',[a('file','timeline','Файл таблицы','Table file',['page size: usually 8 kB'],{items:['page 0','page 1','page 2','…','page 4']})],[],'','Для встроенного heap-метода таблица — последовательность страниц, обычно по 8 КБ. Размер задаётся при сборке сервера, поэтому «всегда 8 КБ» было бы слишком сильным правилом.','For the built-in heap method, a table is a sequence of pages, usually 8 kB each. The size is chosen when building the server, so “always 8 kB” would be too strong.'),
    s('Первая часть адреса выбирает страницу 4.','The first part of the location selects page 4.',[a('file','timeline','Страницы таблицы','Table pages',[],{items:['0','1','2','3','4 ←']}),a('page','page','Страница 4','Page 4',[],{columns:['item','offset','value'],rows:[['1','7800','order 9'],['2','7720','order 17'],['3','7640','order 26']]})],[f('file','page','block 4','internal')],'','Блок нумеруется от нуля. Вторая часть (4,2) не является байтовым смещением: это номер указателя на элемент внутри выбранной страницы.','Blocks are numbered from zero. The second part of (4,2) is not a byte offset; it is an item identifier number within that page.'),
    s('Вторая часть выбирает указатель 2, а он указывает на байты версии заказа 17.','The second part selects item identifier 2, which points to order 17’s tuple bytes.',[a('page','page','Страница 4','Page 4',['ctid = (4,2)'],{columns:['item','offset','value'],rows:[['1','7800','order 9'],['2 →','7720','order 17'],['3','7640','order 26']]}),status('tuple','Версия заказа','Order version',['id = 17','item = Book','qty = 1'])],[f('page','tuple','item 2 → offset 7720','internal')],"SELECT ctid, id, item, qty FROM orders WHERE id = 17;",'Указатель позволяет перемещать байты внутри страницы при уплотнении, сохраняя ссылку на элемент. В примере адрес (4,2) иллюстративный: реальный SELECT может вернуть другой.','The identifier allows tuple bytes to move within a page during compaction while preserving the item reference. Location (4,2) is illustrative; a real SELECT may return a different location.'),
    s('Указатели растут от начала страницы, версии — от конца; между ними свободное место.','Item identifiers grow from the front, tuples from the back; free space lies between.',[a('layout','page','Разметка страницы','Page layout',[],{columns:['region','bytes / direction'],rows:[['header','24 bytes'],['item identifiers','4 bytes each →'],['free space','…'],['tuple data','← from page end']]})],[],'','Новая версия требует места и для своих байтов, и при необходимости для нового указателя. Свободная область не обязана быть такой же большой после нескольких обновлений.','A new tuple requires space for its bytes and, when needed, a new item identifier. The free area can change after several updates.'),
    s('Версия содержит служебный заголовок и значения столбцов.','A tuple contains a system header and column values.',[a('tuple','table','Одна версия','One tuple',[],{columns:['header','meaning'],rows:[['xmin','inserting transaction'],['xmax','delete / lock metadata'],['t_ctid','self / next version'],['user data','17 · Book · 1']]})],[],'','Поля xmin/xmax понадобятся для параллельных транзакций. SQL-столбец ctid обозначает физическое положение этой версии; t_ctid в её заголовке может связывать цепочку обновлений.','The xmin/xmax fields will matter for concurrent transactions. SQL ctid identifies this tuple’s physical location; t_ctid in its header can link an update chain.'),
    s('Адрес версии полезен серверу, а приложению нужен устойчивый ключ id=17.','The server uses tuple locations; the app needs the stable key id=17.',[status('logical','Логический ключ','Logical key',['id = 17']),a('addresses','timeline','Физические адреса','Physical locations',[],{items:['(4,2)','UPDATE →','(4,4)','or another page']})],[f('logical','addresses',b('Версии одной строки','Versions of one row'),'internal')],'','После UPDATE или переписывания таблицы адрес может измениться. Поэтому ctid не заменяет первичный ключ. А для чтения страницы сервер сначала проверяет память.','UPDATE or a table rewrite can change the location. Therefore ctid does not replace a primary key. To read a page, the server first checks memory.')
  ]}),
  c({number:6,id:'buffers',group:0,title:['Страницы в памяти','Pages in memory'],question:['Нужно ли читать страницу с диска при каждом запросе?','Must every query read the page from storage?'],next:['Страница имеет конечный размер. Как поместить в неё длинное значение?','A page has limited space. How can it hold a long value?'],docs:['runtime-config-resource.html','storage-page-layout.html','wal-intro.html'],book:[183,210],steps:[
    s('Запросу нужна страница 4; обслуживающий процесс ищет её в shared buffers.','A query needs page 4; its backend looks in shared buffers.',[backend(['need: orders / page 4']),a('buffers','buckets','Общий буферный кеш','Shared buffer cache',[],{items:['page 1','page 7','empty']})],[f('db','buffers','lookup page 4','internal')],"SELECT item FROM orders WHERE id = 17;",'Shared buffers общие для процессов экземпляра. Они кешируют страницы отношений, а не готовые результаты произвольного SELECT.','Shared buffers are shared by server processes. They cache relation pages, not arbitrary complete SELECT results.'),
    s('Страницы нет в кеше: сервер выделяет буфер и загружает её.','The page is absent: the server chooses a buffer and loads it.',[a('disk','page','Файл таблицы','Table file',['page 4']),a('buffers','buckets','Общий кеш','Shared cache',[],{items:['page 1','page 7','page 4 ←']})],[f('disk','buffers','read page 4','internal')],'','Это промах в кеше Postgres. Операционная система ещё может иметь копию в своём файловом кеше, поэтому промах shared buffers не равен обязательному физическому чтению устройства.','This is a Postgres cache miss. The operating system may still have a copy in its file cache, so a shared-buffer miss does not necessarily mean a physical device read.'),
    s('Пока процесс работает со страницей, pin защищает буфер от замены.','While a backend uses the page, a pin protects its buffer from replacement.',[backend(['pin page 4']),a('buffers','page','Буфер страницы 4','Page 4 buffer',['pin count = 1','id 17 · Book · 1'])],[f('db','buffers','pin / access','internal')],'','Pin удерживает сам буфер, а короткие внутренние блокировки защищают согласованный доступ к данным страницы. Это другой уровень защиты, чем SQL-блокировка строки до COMMIT.','A pin keeps the buffer resident, while short internal locks protect consistent access to its contents. This differs from a SQL row lock held until COMMIT.'),
    s('Следующее чтение находит страницу в кеше и получает значения без нового чтения файла.','The next read finds the page in cache without another file read.',[backend(['SELECT id = 17']),a('buffers','page','Буфер страницы 4','Page 4 buffer',['cache hit','id 17 · Book · 1']),client(['Book × 1'])],[f('db','buffers','hit','internal'),f('buffers','app','Book · 1','reply')],'','Кеш экономит ввод-вывод для повторных обращений. Проверки видимости всё ещё выполняются: наличие страницы в памяти не делает все её версии видимыми каждому запросу.','The cache saves I/O for repeated access. Visibility checks still occur: being in memory does not make every tuple visible to every query.'),
    s('UPDATE меняет страницу в памяти и делает буфер грязным.','UPDATE changes the page in memory and marks the buffer dirty.',[backend(['qty: 1 → 2']),a('buffers','page','Грязный буфер','Dirty buffer',['page 4 · dirty','id 17 · qty 2']),a('disk','page','Старая копия файла','Older file copy',['page 4','id 17 · qty 1'])],[f('db','buffers','UPDATE','internal')],"UPDATE orders SET qty = 2 WHERE id = 17;",'На рисунке подчёркнута разница копий, а не обещание немедленной записи файла. За надёжность изменения отвечает журнал; обновление также создаёт новую версию строки, которую подробно покажем позже.','The scene emphasizes the difference between copies, not an immediate file write. The log protects durability; UPDATE also creates a new row version, which we examine later.'),
    s('Грязную страницу можно записать позже, когда сохранён соответствующий WAL.','The dirty page can be written later, once its corresponding WAL is durable.',[a('buffers','page','Грязный буфер','Dirty buffer',['page 4 · dirty']),a('disk','page','Файл таблицы','Table file',['page 4']),status('rule','Условие записи','Write condition',['WAL durable first'])],[f('rule','buffers','WAL flush ✓','sync'),f('buffers','disk','write page 4','internal')],'','Запись могут выполнять разные процессы, включая checkpointer и backend. Грязный буфер нельзя просто забыть при вытеснении. Сначала разберём ещё одно ограничение страницы — большие значения.','Different processes can write it, including the checkpointer and a backend. A dirty buffer cannot simply be forgotten during replacement. First we examine another page limitation: large values.')
  ]}),
  c({number:7,id:'toast',group:0,title:['Значение больше страницы','A value larger than a page'],question:['Что делать с описанием товара длиной 20 000 символов?','What happens to a 20,000-character product description?'],next:['Значения разместились. Как сервер сохраняет их при внезапном сбое?','The values fit. How does the server preserve them across a crash?'],docs:['storage-toast.html','storage-page-layout.html'],book:[33,38],steps:[
    s('Описание на 20 000 символов нельзя просто растянуть через границы heap-страницы.','A 20,000-character description cannot simply stretch across heap-page boundaries.',[a('value','box','Длинное описание','Long description',['20 000 characters']),a('page','page','Heap-страница','Heap page',['usually 8 kB'])],[f('value','page',b('Слишком велико','Too large'),'request')],"ALTER TABLE orders ADD COLUMN note text;\nUPDATE orders SET note = repeat('x', 20000) WHERE id = 17;",'Обычная версия heap-строки не пересекает страницы. Для подходящих переменных типов Postgres применяет TOAST: сжатие и/или внешнее хранение больших значений.','An ordinary heap tuple does not span pages. For eligible variable-length types, Postgres uses TOAST: compression and/or out-of-line storage of large values.'),
    s('Сначала подходящее значение можно сжать и оставить прямо в строке.','An eligible value may first be compressed and kept inside the tuple.',[a('value','box','Повторяющийся текст','Repetitive text',['xxxxxxxx…']),a('page','page','Значение в строке','Inline value',['compressed note','20 000 → smaller'])],[f('value','page','compress','internal')],'','Повторяющийся текст нашего SQL хорошо сжимается, поэтому этот конкретный пример не доказывает внешнее хранение. Стратегия и метод сжатия зависят от типа и настроек столбца.','The repeated text in our SQL compresses well, so this particular example does not prove out-of-line storage. The strategy and compression method depend on the type and column settings.'),
    s('Если строка всё ещё велика, значение делится на части во внешней TOAST-таблице.','If the tuple is still too large, the value is split into chunks in a TOAST table.',[a('page','page','Основная строка','Main tuple',['id = 17','note → TOAST pointer']),a('toast','table','Части значения','Value chunks',[],{columns:['chunk_id','chunk_seq','chunk_data'],rows:[[900,0,'part 0'],[900,1,'part 1'],[900,2,'part 2'],[900,'…','…']]})],[f('page','toast','value 900','internal')],'','Здесь отдельная ветка для плохо сжимаемого большого значения. Главная строка содержит короткую ссылку, а связанная TOAST-таблица хранит части примерно по 2 КБ каждая.','This is a separate branch for a large, poorly compressible value. The main tuple holds a short pointer; its associated TOAST table stores chunks of roughly 2 kB each.'),
    s('Запрос только номера заказа может обойтись без сборки длинного описания.','A query for only the order ID can avoid reconstructing the long description.',[backend(['SELECT id']),a('page','page','Основная строка','Main tuple',['id = 17','note → pointer']),a('toast','table','TOAST','TOAST',[b('Пока не требуется','Not needed yet')],{columns:['chunk_id','seq'],rows:[[900,0],[900,1],[900,2]]})],[f('db','page','id only','internal')],"SELECT id FROM orders WHERE id = 17;",'Наличие большого столбца не означает, что каждый SELECT обязан прочитать и распаковать его целиком. Это одна из причин хранить большие значения отдельно от основной строки.','A large column does not mean every SELECT must fetch and decompress it in full. This is one reason to keep large values outside the main tuple.'),
    s('Когда нужен note, сервер находит части и возвращает одно логическое значение.','When note is needed, the server locates its chunks and returns one logical value.',[a('toast','table','Части по порядку','Chunks in sequence',[],{columns:['seq','data'],rows:[[0,'part 0'],[1,'part 1'],[2,'part 2']]}),backend([b('Сборка значения','Reconstruct value')]),client(['note = complete text'])],[f('toast','db','0 → 1 → 2','internal'),f('db','app','note','reply')],"SELECT note FROM orders WHERE id = 17;",'Приложение работает с одним text-значением независимо от физического размещения. Страницы основной и TOAST-таблицы нуждаются в той же защите от сбоев; теперь откроем WAL.','The app works with one text value regardless of its physical placement. Both main-table and TOAST pages need crash protection; now we open WAL.')
  ]}),
  c({number:8,id:'wal',group:1,title:['Сначала журнал','The log comes first'],question:['Как защитить изменение, если страница таблицы ещё в памяти?','How can a change survive while its table page is still in memory?'],next:['Журнал сохранён. В какой момент можно подтвердить всю транзакцию?','The log is durable. When can the whole transaction be acknowledged?'],docs:['wal-intro.html','wal-configuration.html','datatype-pg-lsn.html'],book:[211,218],steps:[
    s('В памяти уже qty=2, а в файле таблицы ещё qty=1.','Memory already contains qty=2, while the table file still contains qty=1.',[a('buffer','page','Страница в памяти','Page in memory',['page 4 · qty 2 · dirty']),a('disk','page','Страница в файле','Page in the file',['page 4 · qty 1'])],[],"UPDATE orders SET qty = 2 WHERE id = 17;",'Сам по себе буфер не переживёт потерю памяти. Записывать все изменённые страницы при каждом COMMIT дорого, особенно когда транзакция затрагивает много разных файлов.','A buffer alone cannot survive memory loss. Flushing every changed page at each COMMIT is expensive, especially when a transaction touches many files.'),
    s('Для изменения создаётся WAL-запись, достаточная для повторения работы.','The change generates a WAL record sufficient to redo the work.',[a('buffer','page','Изменённая страница','Changed page',['page 4 · qty 2']),wal(['0/100 · HEAP update','end: 0/140'])],[f('buffer','wal','describe change','internal')],'','Надпись HEAP update — краткое описание низкоуровневой записи, а не сохранённый текст UPDATE. Позиции LSN здесь учебные; журнал содержит сведения о страницах и изменениях.','HEAP update is a shorthand for a low-level record, not stored UPDATE text. These LSN positions are illustrative; WAL contains page and change information.'),
    s('WAL buffers пока тоже находятся в памяти. Это ещё не надёжное сохранение.','WAL buffers are also in memory. This is not yet durable storage.',[wal(['HEAP update','insert end: 0/140'],['WAL buffers · RAM']),status('lsn','Позиция в странице','Page position',['page LSN = 0/140']),a('disk','page','Файл таблицы','Table file',['qty 1'])],[],'SELECT pg_current_wal_insert_lsn();','LSN — позиция в байтовом потоке журнала. Страница хранит LSN относящегося к ней последнего изменения; он помогает соблюдать порядок записи и повторного применения.','An LSN is a position in the WAL byte stream. A page keeps the LSN of its latest relevant change; this helps enforce write and replay ordering.'),
    s('Write переносит WAL в файловую систему, где его ещё может держать кеш ОС.','Write sends WAL to the filesystem, where the OS cache may still hold it.',[wal(['end: 0/140'],['WAL buffers']),a('os','box','Кеш файловой системы','Filesystem cache',['WAL through 0/140']),status('durable','Устойчивый носитель','Durable storage',[b('Новая запись ещё не гарантирована','New record not yet guaranteed')])],[f('wal','os','write','internal')],'SELECT pg_current_wal_lsn();','Запись в файловую систему и надёжный flush — разные этапы. После обычного write внезапное отключение питания ещё может потерять содержимое кеша.','A filesystem write and a durable flush are different stages. After a normal write, sudden power loss may still lose cached contents.'),
    s('Flush обеспечивает сохранение WAL до позиции 0/140 на устойчивом хранении.','Flush makes WAL through 0/140 durable.',[a('os','box','Кеш ОС','OS cache',['WAL through 0/140']),wal(['HEAP update','flush end: 0/140'],[b('Устойчиво сохранено','Durably stored')])],[f('os','wal','flush','sync')],'SELECT pg_current_wal_flush_lsn();','При исправном стеке хранения синхронизация обеспечивает требуемую гарантию устойчивости. Не каждый write вызывает отдельную синхронизацию: одну операцию можно разделить между несколькими транзакциями.','With a correctly functioning storage stack, synchronization provides the required durability guarantee. Not every write requires a separate sync; several transactions can share one.'),
    s('Теперь страницу с LSN 0/140 разрешено записать в файл таблицы.','The page with LSN 0/140 can now be written to the table file.',[wal(['flush LSN = 0/140']),a('buffer','page','Грязная страница','Dirty page',['page LSN = 0/140','qty 2']),a('disk','page','Файл таблицы','Table file',['qty 2'])],[f('wal','buffer','WAL flush ≥ page LSN','sync'),f('buffer','disk','write page','internal')],'','Главное правило WAL: связанные журнальные сведения должны стать устойчивыми раньше страницы данных. Порядок касается сохранения, а не запрета сначала изменить буфер в памяти.','The WAL rule is that the relevant log records must become durable before the data page does. This constrains persistence, not whether a buffer may first be changed in memory.'),
    s('Один последовательный журнал защищает изменения многих страниц.','One sequential log protects changes to many pages.',[a('pages','buckets','Изменённые страницы','Changed pages',[],{items:['orders / 4','orders / 9','index / 2']}),wal(['HEAP update','HEAP insert','BTREE insert'])],[f('pages','wal',b('Общий поток WAL','Shared WAL stream'),'internal')],'','WAL уменьшает необходимость немедленно синхронизировать разрозненные файлы. Но наличие записи об изменении ещё не означает успешную фиксацию транзакции: ей нужна собственная завершающая запись.','WAL reduces the need to synchronize scattered files immediately. A change record alone does not mean its transaction committed: the transaction needs its own completion record.')
  ]}),
  c({number:9,id:'commit',group:1,title:['Когда ответить «сохранено»','When to reply “saved”'],question:['Изменения попали в WAL. Что ещё отделяет их от успешного COMMIT?','Changes reached WAL. What still separates them from a successful COMMIT?'],next:['Журнал растёт. Как ограничить работу при восстановлении?','The log grows. How can recovery work be bounded?'],docs:['wal-intro.html','wal-configuration.html','transaction-id.html'],book:[234,238],steps:[
    s('Приложение ждёт: транзакция T500 изменила заказ, но ещё не завершилась.','The app waits: transaction T500 changed the order but has not finished.',[client([b('Ответа ещё нет','No reply yet')]),backend(['T500 · open']),wal(['T500 · HEAP update'])],[],'BEGIN;\nUPDATE orders SET qty = 2 WHERE id = 17;','Обозначение T500 пока служит меткой транзакции. Позднее разберём, как настоящий номер выделяется и хранится; здесь важна граница между изменением и фиксацией.','T500 currently labels the transaction. Later we explain real transaction ID allocation and storage; here the important boundary is between a change and a commit.'),
    s('COMMIT добавляет запись о завершении T500 в общий журнал.','COMMIT adds T500’s completion record to the shared log.',[backend(['COMMIT T500']),wal(['T500 · HEAP update','T500 · COMMIT @ 0/180'])],[f('db','wal','commit record','internal')],'COMMIT;','До ответа клиенту стандартный синхронный COMMIT должен обеспечить сохранение WAL до конца своей commit-записи. Значение 0/180 — учебная конечная позиция.','Before replying, a normal synchronous COMMIT must ensure WAL is durable through the end of its commit record. 0/180 is an illustrative end position.'),
    s('Один flush может сохранить COMMIT сразу T500 и T501.','One flush can make both T500 and T501 commits durable.',[wal(['T500 · COMMIT → 0/180','T501 · COMMIT → 0/1C0']),status('flush','Общий flush','Shared flush',['durable through 0/1C0'])],[f('wal','flush','group commit','sync')],'','Поскольку WAL общий и упорядоченный, синхронизация до 0/1C0 покрывает обе записи. Это group commit: надёжность не требует отдельного fsync для каждой маленькой транзакции.','Because WAL is shared and ordered, syncing through 0/1C0 covers both records. This is group commit: durability does not require a separate fsync for every small transaction.'),
    s('После фиксации сервер отправляет успех; страницы таблицы ещё могут оставаться грязными.','After commit, the server sends success; table pages may still be dirty.',[backend(['T500 · committed']),client([b('Заказ сохранён','Order saved')]),a('buffer','page','Буфер таблицы','Table buffer',['qty 2 · may be dirty'])],[f('db','app','COMMIT','reply')],'','Надёжно сохранённый WAL позволяет восстановить изменение, даже если новая страница таблицы пока не записана. Метаданные статуса транзакции и видимость для читателей раскроем отдельно.','Durable WAL can restore the change even if the new table page is not yet written. We examine transaction-status metadata and reader visibility separately.'),
    s('Новый читатель после COMMIT получает qty=2.','A new reader after COMMIT obtains qty=2.',[client(['new SELECT']),orders([[17,42,'Book',2]],[b('Зафиксированное значение','Committed value')])],[f('app','orders','SELECT'),f('orders','app','qty = 2','reply')],"SELECT qty FROM orders WHERE id = 17;",'Здесь читатель начинает после успешной фиксации и берёт новый снимок. Уже существовавший старый снимок может продолжить видеть прежнюю версию — это тема многоверсионности.','Here the reader starts after the successful commit and takes a fresh snapshot. A preexisting older snapshot may still see the previous version; MVCC explains that later.'),
    s('Если COMMIT сохранился, а ответ потерялся, результат для клиента неизвестен.','If COMMIT is durable but its reply is lost, the client does not know the outcome.',[wal(['T500 · COMMIT durable']),backend([b('Соединение оборвалось','Connection lost')]),client([b('Не получил ответ','No reply received')])],[f('db','app',b('Ответ потерян','Reply lost'),'wait')],'','Отсутствие подтверждения не доказывает откат. Повтор бизнес-действия должен учитывать возможную успешную фиксацию; устойчивый идентификатор заказа помогает приложению проверить результат.','A missing reply does not prove rollback. Retrying a business action must account for a possible successful commit; a stable order ID helps the app check the outcome.')
  ]}),
  c({number:10,id:'checkpoint',group:1,title:['Откуда начинать восстановление','Where recovery can begin'],question:['Нужно ли после сбоя повторять WAL с начала жизни сервера?','Must crash recovery replay WAL from the server’s beginning?'],next:['Контрольная точка завершена. Как Postgres применит журнал после сбоя?','The checkpoint is complete. How does Postgres replay the log after a crash?'],docs:['wal-configuration.html','functions-info.html','runtime-config-wal.html'],book:[218,223],steps:[
    s('Чем больше изменений накопилось только в WAL, тем больше потенциальная работа REDO.','More changes preserved only in WAL can mean more REDO work.',[wal(['old changes','more changes','recent changes']),a('disk','page','Файлы таблиц','Table files',[b('Некоторые копии старые','Some copies are older')])],[],'','WAL обеспечивает восстановимость, но не обязан повторяться бесконечно далеко назад. Контрольная точка создаёт новую безопасную границу восстановления.','WAL makes recovery possible, but replay need not reach arbitrarily far into the past. A checkpoint establishes a new safe recovery boundary.'),
    s('В начале checkpoint фиксируется REDO-позиция и набор нужных грязных буферов.','Checkpoint start establishes a REDO position and the dirty buffers that must be saved.',[wal(['REDO @ 0/200']),a('buffers','buckets','Буферы в начале','Buffers at start',[],{items:['page 4 · dirty *','page 9 · dirty *','page 12 · clean']})],[f('wal','buffers','checkpoint start','internal')],'CHECKPOINT;','Звёздочка отмечает обязательную работу этой контрольной точки. CHECKPOINT — действительная команда принудительного запуска; на практике checkpointer также запускается автоматически.','An asterisk marks required work for this checkpoint. CHECKPOINT is the real command for a forced run; the checkpointer also runs automatically.'),
    s('Checkpointer записывает отмеченные страницы постепенно, соблюдая правило WAL.','The checkpointer gradually writes the marked pages while respecting the WAL rule.',[a('buffers','buckets','Отмеченные буферы','Marked buffers',[],{items:['page 4 → write','page 9 → write']}),a('disk','buckets','Файлы отношений','Relation files',[],{items:['page 4 saved','page 9 saved']})],[f('buffers','disk','spread writes','internal')],'','Работа распределяется во времени, чтобы уменьшить всплеск ввода-вывода. Страницу может успеть записать и другой процесс; важно выполнение общей гарантии, а не единственный исполнитель.','Writes are spread over time to reduce I/O bursts. Another process may write a page first; the requirement is the shared guarantee, not a single writer.'),
    s('Параллельные запросы продолжаются: уже записанная страница может снова стать грязной.','Queries continue: a page already written can become dirty again.',[a('buffers','buckets','Кеш продолжает меняться','The cache keeps changing',[],{items:['page 4 · dirty again','page 9 · clean','page 12 · newly dirty']}),wal(['REDO @ 0/200','new changes > 0/200'])],[f('buffers','wal','new changes','internal')],'','Checkpoint не останавливает мир и не гарантирует пустой список грязных буферов в момент завершения. Более новые изменения защищены WAL после выбранной REDO-позиции.','A checkpoint does not stop the world or guarantee zero dirty buffers at completion. Newer changes are protected by WAL after the chosen REDO position.'),
    s('После успешного завершения pg_control указывает на новую контрольную точку.','After successful completion, pg_control points to the new checkpoint.',[wal(['REDO @ 0/200','checkpoint end @ 0/380']),status('control','Управляющий файл','Control file',['checkpoint: 0/380','redo: 0/200'])],[f('wal','control','completed checkpoint','sync')],'SELECT checkpoint_lsn, redo_lsn FROM pg_control_checkpoint();','Место завершающей записи и место начала REDO различаются. До успешного завершения безопасной остаётся предыдущая контрольная точка.','The completion record location and the REDO start location differ. Until successful completion, the previous checkpoint remains the safe one.'),
    s('Теперь REDO начинается с 0/200; старые сегменты можно убрать, если они больше никому не нужны.','REDO can now start at 0/200; older segments can go only when no other consumer needs them.',[wal(['older WAL','REDO @ 0/200','replay after crash']),status('retention','Другие потребители','Other consumers',['archive','replication slots'])],[f('retention','wal',b('Могут удерживать WAL','May retain WAL'),'wait')],'','Архивирование, слоты репликации и другие требования могут удерживать сегменты после checkpoint. Поэтому контрольная точка не означает немедленное удаление всего предыдущего WAL.','Archiving, replication slots, and other requirements can retain segments after a checkpoint. A checkpoint therefore does not mean that all preceding WAL immediately disappears.')
  ]}),
  c({number:11,id:'recovery',group:1,title:['Вернуться после сбоя','Recover after a crash'],question:['В памяти были изменения, а питание исчезло. Как собрать согласованное состояние?','Memory contained changes when power failed. How can a consistent state be rebuilt?'],next:['Что меняется, если отвечать клиенту раньше надёжного flush?','What changes if the server replies before a durable flush?'],docs:['wal-intro.html','wal-configuration.html','wal-reliability.html'],book:[223,226],steps:[
    s('После сбоя память потеряна; остались страницы файлов и устойчивый WAL.','After the crash, memory is gone; data files and durable WAL remain.',[a('disk','page','Файл таблицы','Table file',['page 4 · qty 1','page LSN = 0/100']),wal(['0/200 · checkpoint REDO','0/240 · update qty 2','0/280 · COMMIT T500'])],[],'','Состояние файла может отставать от подтверждённого COMMIT. Это ожидаемо: восстановление использует журнал, а не надеется на сохранность кеша.','The file may lag behind an acknowledged COMMIT. This is expected: recovery uses WAL rather than relying on the cache surviving.'),
    s('Startup читает pg_control и находит REDO последнего завершённого checkpoint.','Startup reads pg_control and finds REDO for the last completed checkpoint.',[status('control','pg_control','pg_control',['state: interrupted','redo: 0/200']),wal(['start → 0/200','0/240 · update','0/280 · COMMIT'])],[f('control','wal','REDO location','internal')],'','Для обычного crash recovery используется сохранённая контрольная информация. Восстановление из физической копии дополнительно учитывает сведения самой резервной копии.','Ordinary crash recovery uses saved checkpoint information. Recovery from a physical backup also uses the backup’s own metadata.'),
    s('REDO повторяет нужное изменение: страница снова получает qty=2.','REDO replays the required change, restoring qty=2 on the page.',[wal(['0/240 · update qty 2']),a('buffer','page','Восстанавливаемая страница','Page being recovered',['qty 1 → 2','page LSN advances'])],[f('wal','buffer','REDO','internal')],'','Для обычных записей сравнение LSN позволяет не повторять уже применённую к странице работу. Полные образы страниц обеспечивают восстановление повреждённого частичной записью содержимого.','For ordinary records, LSN checks avoid redoing work already applied to the page. Full-page images can restore contents affected by a partial page write.'),
    s('Изменение T501 может восстановиться физически, но без COMMIT не станет видимым результатом.','T501’s change may be physically replayed, yet without COMMIT it does not become visible data.',[wal(['T500 · COMMIT','T501 · INSERT','crash · no T501 COMMIT']),a('heap','page','После REDO','After REDO',[],{columns:['tuple','transaction','visibility'],rows:[['order 17','T500','committed'],['order 18','T501','not committed']]})],[f('wal','heap','REDO records','internal')],'','REDO — не фильтр только успешно завершённых транзакций. Postgres использует статусы и MVCC, чтобы скрыть последствия незавершённых операций; обычного прохода физического undo по всем строкам не требуется.','REDO does not replay only successful transactions. Postgres uses status information and MVCC to hide unfinished changes; it does not require a normal physical-undo pass over all affected tuples.'),
    s('После восстановления новый SELECT видит зафиксированный заказ 17 с qty=2.','After recovery, a new SELECT sees committed order 17 with qty=2.',[backend([b('Восстановление завершено','Recovery complete')]),orders([[17,42,'Book',2]]),client(['qty = 2'])],[f('db','orders','SELECT','internal'),f('orders','app','qty = 2','reply')],"SELECT id, qty FROM orders WHERE id = 17;",'Сцена показывает ожидаемое состояние модели после crash recovery, а не результат запущенного здесь сервера. Незавершённая вставка T501 остаётся невидимой.','This scene shows the model’s expected post-recovery state, not output from a server executed here. T501’s unfinished insertion remains invisible.'),
    s('Восстановленное состояние сохраняется; сервер снова принимает обычные запросы.','The recovered state is saved, and the server accepts normal queries again.',[a('disk','page','Восстановленные файлы','Recovered files',['order 17 · qty 2']),wal(['end-of-recovery checkpoint']),client([b('Можно продолжать','Ready to continue')])],[f('wal','disk','checkpoint','sync'),f('disk','app',b('Сервер готов','Server ready'),'reply')],'','Журнал позволил пережить потерю памяти. Следующий выбор касается другой границы: должен ли клиент обязательно ждать сохранения commit-записи перед ответом.','WAL made memory loss survivable. The next choice concerns a different boundary: whether a client must wait for its commit record to become durable before receiving a reply.')
  ]}),
  c({number:12,id:'durability',group:1,title:['Цена раннего подтверждения','The cost of an early reply'],question:['Можно ли уменьшить задержку COMMIT и какую гарантию это меняет?','Can COMMIT latency be reduced, and which guarantee changes?'],next:['WAL переживает сбой процесса. А если потерян весь диск?','WAL survives a crash. What if the entire disk is lost?'],docs:['wal-async-commit.html','runtime-config-wal.html','wal-reliability.html'],book:[234,246],steps:[
    s('В обычном режиме ответ ждёт локального устойчивого WAL.','Normally, the reply waits for local durable WAL.',[a('line','timeline','Порядок синхронного COMMIT','Synchronous COMMIT order',[],{items:['commit record','WAL flush','success reply']})],[],'SHOW synchronous_commit;\nSHOW fsync;','В этом локальном примере synchronous_commit=on и fsync=on; синхронные standby не настроены. Поэтому требуемая граница ответа — локальный flush, а не запись всех страниц таблиц.','In this local example, synchronous_commit=on and fsync=on, with no synchronous standbys configured. The reply boundary is local WAL flush, not every table-page write.'),
    s('При synchronous_commit=off успех может уйти до flush commit-записи.','With synchronous_commit=off, success may precede the commit record’s flush.',[a('line','timeline','Асинхронный COMMIT','Asynchronous COMMIT',[],{items:['commit record','success reply','risk window','WAL flush later']})],[],'SET synchronous_commit = off;','Настройка меняет ожидание клиента, а не отменяет WAL и не отключает правила согласованной записи данных. Между ответом и flush появляется окно возможной потери последних транзакций.','This changes client waiting; it does not remove WAL or disable consistent-write rules. The interval between reply and flush is a window in which recent transactions can be lost.'),
    s('Если WAL writer успевает выполнить flush, раннее подтверждение тоже переживает последующий сбой.','If the WAL writer flushes in time, the early-acknowledged commit survives a later crash.',[wal(['commit buffered','commit durable ✓']),status('writer','WAL writer','WAL writer',[b('Фоновый flush','Background flush')]),client([b('Ответ уже получен','Reply already received')])],[f('writer','wal','flush','sync')],'','Фоновый процесс регулярно продвигает устойчивую позицию WAL. Фактическое окно зависит от активности и настроек; анимация не приписывает ему гарантированное произвольное число миллисекунд.','A background process regularly advances durable WAL. The actual window depends on activity and settings; this animation does not invent a guaranteed millisecond value.'),
    s('Если сбой случился раньше flush, недавно подтверждённая транзакция может исчезнуть.','If a crash happens before flush, a recently acknowledged transaction may disappear.',[a('line','timeline','Сбой внутри окна','Crash within the window',[],{items:['success reply','CRASH','commit not durable']}),orders([[17,42,'Book',1]],[b('Предыдущее состояние','Previous state')])],[f('line','orders','recovery','internal')],'','После восстановления возможна потеря целого недавнего результата, например возврат qty с 2 к 1. Это иной риск, чем повреждение произвольных страниц из-за отключения синхронизации хранения.','Recovery may lose a whole recent result, such as reverting qty from 2 to 1. That differs from arbitrary page corruption caused by disabling storage synchronization.'),
    s('synchronous_commit=off и fsync=off — разные решения с разными последствиями.','synchronous_commit=off and fsync=off are different choices with different consequences.',[a('choices','table','Разные гарантии','Different guarantees',[],{columns:['setting','effect'],rows:[['sync_commit=off','recent commits may be lost'],['fsync=off','crash may corrupt data'],['both on','durable local commit']]})],[],'SET synchronous_commit = on;','Для дальнейшего рассказа возвращаем стандартное ожидание надёжной фиксации. Даже оно не заменяет отдельную резервную копию: локальный WAL может быть потерян вместе с накопителем.','For the rest of the story we return to normal durable-commit waiting. Even that does not replace a separate backup: local WAL can be lost with the storage device.')
  ]}),
  c({number:13,id:'backup',group:1,title:['Копия и восстановление во времени','A backup and recovery through time'],question:['Как восстановиться после потери диска или ошибочного удаления?','How can data be recovered after disk loss or an accidental deletion?'],next:['Данные защищены. Почему одновременно работающим читателям нужны разные версии?','Data is protected. Why do concurrent readers need different versions?'],docs:['backup.html','backup-dump.html','continuous-archiving.html','app-pgbasebackup.html'],book:[211,213],steps:[
    s('Файлы таблиц и WAL на одном потерянном диске исчезают вместе.','Table files and WAL disappear together if their shared disk is lost.',[a('disk','box','Потерянный накопитель','Lost device',['table files ✕','local WAL ✕']),status('copy','Отдельная копия','Separate backup',[b('Нужна заранее','Must exist beforehand')])],[],'','Crash recovery предполагает, что нужные файлы уцелели. Резервное копирование добавляет независимый путь восстановления; сама реплика тоже не сохраняет удалённые данные навечно.','Crash recovery assumes the required files survived. A backup adds an independent recovery path; a replica does not preserve deleted data forever either.'),
    s('Логическая копия сохраняет определения и данные для последующего создания объектов.','A logical dump saves definitions and data for rebuilding objects.',[a('source','table','Исходная база','Source database',[],{columns:['id','item','qty'],rows:[[17,'Book',2],[19,'Pencil',3]]}),a('dump','box','Логическая копия','Logical dump',['schema + table data','pg_dump / pg_restore'])],[f('source','dump',b('Согласованный dump','Consistent dump'),'internal')],'','pg_dump — внешняя программа, а не SQL-команда. Она делает согласованную логическую копию одной базы при продолжающейся работе; роли и другие общие объекты требуют отдельного учёта.','pg_dump is an external program, not a SQL command. It creates a consistent logical dump of one database while work continues; roles and other shared objects need separate handling.'),
    s('Физическая базовая копия сохраняет файлы кластера и необходимые сведения для восстановления.','A physical base backup saves cluster files and the metadata needed for recovery.',[a('source','server','Работающий кластер','Running cluster',['databases + metadata']),a('base','box','Базовая копия 10:00','Base backup 10:00',['physical files','required WAL'])],[f('source','base','base backup','internal')],'','Согласованный протокол физической копии учитывает изменения во время копирования. Произвольное копирование нескольких файлов работающего сервера не равно корректной базовой копии.','A proper physical-backup protocol accounts for changes during copying. Copying arbitrary files from a running server is not equivalent to a valid base backup.'),
    s('Непрерывный архив WAL дополняет базовую копию последующими изменениями.','A continuous WAL archive extends the base backup with later changes.',[a('base','box','Базовая копия','Base backup',['10:00']),wal(['10:01 · INSERT order 17','10:04 · qty 1 → 2','10:06 · DELETE order 17'])],[f('base','wal',b('Продолжить историю','Extend the history'),'internal')],'SELECT pg_walfile_name(pg_current_wal_lsn());','Для восстановления нужны базовая копия и непрерывная цепочка требуемых WAL-сегментов. Один недостающий участок может лишить возможности пройти к нужной точке.','Recovery needs the base backup plus an unbroken sequence of required WAL segments. A missing segment can prevent reaching the intended target.'),
    s('Цель 10:05 останавливает воспроизведение до ошибочного DELETE в 10:06.','A 10:05 target stops replay before the accidental DELETE at 10:06.',[wal(['10:01 · INSERT ✓','10:04 · UPDATE ✓','10:05 · target','10:06 · DELETE ✕']),orders([[17,42,'Book',2]])],[f('wal','orders','replay to target','internal')],'','Это point-in-time recovery физической копии. Восстанавливается состояние кластера до выбранной точки, а не выполняется отмена одной команды в продолжающей жить исходной базе.','This is point-in-time recovery from a physical backup. It reconstructs cluster state at a chosen target; it does not undo one command inside the still-running original database.'),
    s('Результат восстановления нужно проверить чтением нужных данных.','The recovery result must be checked by reading the required data.',[orders([[17,42,'Book',2]]),client(['17 · Book · 2',b('Цель восстановлена','Target recovered')])],[f('app','orders','SELECT'),f('orders','app','order 17','reply')],"SELECT id, item, qty FROM orders WHERE id = 17;",'В модели заказ снова существует с qty=2. Наличие backup-файла само по себе ещё не демонстрирует успешное восстановление; проверяем достижимую точку и содержимое. Теперь вернёмся к читателям работающей базы.','In the model, order 17 exists again with qty=2. A backup file alone does not demonstrate successful recovery; the reachable target and data matter. Now we return to readers in a running database.')
  ]}),
  c({number:14,id:'versions',group:2,title:['Почему UPDATE оставляет две версии','Why UPDATE leaves two versions'],question:['Как изменить заказ, не сломав уже начавшееся чтение?','How can an order change without disrupting a read already in progress?'],next:['Версии помечены номерами транзакций. Откуда берутся эти номера?','Versions carry transaction IDs. Where do those IDs come from?'],docs:['mvcc-intro.html','ddl-system-columns.html','storage-page-layout.html'],book:[80,90],steps:[
    s('Читатель начал запрос, когда заказ 17 имел qty=1.','A reader starts its query while order 17 has qty=1.',[a('reader','client','Читатель','Reader',['snapshot before T500']),versions([['(0,1)',400,0,'qty 1']])],[f('reader','heap','SELECT','request')],"SELECT qty FROM orders WHERE id = 17;",'В этой новой ветке снова начинаем с qty=1; версию создала ранее зафиксированная транзакция 400. Нулевой xmax в этом исходном состоянии означает отсутствие отмеченного удаления или блокировки.','This new branch starts again at qty=1, created by an earlier committed transaction, 400. In this initial state, zero xmax means no recorded deletion or lock.'),
    s('T500 создаёт новую версию qty=2, а старую помечает своим номером.','T500 creates a new qty=2 version and marks the old one with its ID.',[a('writer','client','Писатель T500','Writer T500',['UPDATE qty = 2']),versions([['(0,1)',400,500,'qty 1'],['(0,2)',500,0,'qty 2']])],[f('writer','heap','UPDATE','internal')],"BEGIN;\nUPDATE orders SET qty = 2 WHERE id = 17;",'У старой версии xmax=500, у новой xmin=500. В простом примере обе помещаются на одной странице; в общем случае новая версия может оказаться в другом месте.','The old version has xmax=500; the new one has xmin=500. Both fit on one page in this simple example; a new version can also be stored elsewhere.'),
    s('До COMMIT чужой читатель видит qty=1, а не незавершённое qty=2.','Before COMMIT, another reader sees qty=1, not the unfinished qty=2.',[a('reader','client','Читатель','Reader',['result: qty 1']),versions([['(0,1)',400,500,'visible: qty 1'],['(0,2)',500,0,'not committed']]),status('tx','Статус T500','T500 status',['in progress'])],[f('heap','reader','qty = 1','reply')],'','Ненулевой xmax ещё не делает старую версию невидимой: удаляющая транзакция пока не зафиксирована. Так MVCC отделяет наличие байтов от доступности результата.','A nonzero xmax does not yet hide the old version: the deleting transaction has not committed. MVCC separates bytes existing from a result being visible.'),
    s('После COMMIT новый снимок видит qty=2, а прежний снимок может продолжать видеть qty=1.','After COMMIT, a fresh snapshot sees qty=2, while the older snapshot may still see qty=1.',[versions([['(0,1)',400,500,'qty 1'],['(0,2)',500,0,'qty 2']]),a('reader','client','Прежний снимок','Older snapshot',['qty = 1']),a('newReader','client','Новый снимок','Fresh snapshot',['qty = 2'])],[f('heap','reader','old version','reply'),f('heap','newReader','new version','reply')],'COMMIT;','Снимок старого запроса сохраняет собственную границу видимости, даже когда статус T500 изменился. Правила выбора одной подходящей версии скоро разберём по числам.','An older query’s snapshot preserves its visibility boundary even after T500’s status changes. We will soon calculate which version is selected using explicit numbers.'),
    s('DELETE T501 помечает текущую версию, а не обязан немедленно стирать её байты.','DELETE T501 marks the current version rather than immediately erasing its bytes.',[a('writer','client','Удаление T501','Delete T501',['DELETE id = 17']),versions([['(0,1)',400,500,'qty 1'],['(0,2)',500,501,'qty 2']])],[f('writer','heap','set xmax = 501','internal')],"BEGIN;\nDELETE FROM orders WHERE id = 17;\nCOMMIT;",'После фиксации удаления новый обычный запрос не найдёт заказа. Старый снимок всё ещё может нуждаться в одной из сохранённых версий; физическая очистка поэтому отложена.','After the delete commits, a fresh ordinary query finds no order. An older snapshot may still need one of the retained versions, so physical cleanup is deferred.'),
    s('Логически заказа уже нет, физически его версии ещё могут лежать на странице.','The order is logically gone, yet its physical versions may remain on the page.',[orders([],[b('Новый SELECT: 0 строк','Fresh SELECT: 0 rows')]),versions([['(0,1)',400,500,'old bytes'],['(0,2)',500,501,'old bytes']])],[],"SELECT * FROM orders WHERE id = 17;",'MVCC требует узнавать создавшую и изменившую версии транзакции. Сначала разберём сами идентификаторы, затем статусы и снимки; удаление ненужных версий станет отдельной историей.','MVCC must identify the transactions that created and superseded each version. We first examine IDs, then statuses and snapshots; removing unnecessary versions gets its own story.')
  ]}),
  c({number:15,id:'xid',group:2,title:['Номер транзакции появляется не сразу','A transaction ID is assigned later'],question:['Получает ли каждый BEGIN следующий глобальный номер?','Does every BEGIN receive the next global ID?'],next:['Номер записан в версии. Где узнать, завершилась ли эта транзакция?','The ID is stored in a tuple. Where can its outcome be found?'],docs:['transaction-id.html','functions-info.html','xact-locking.html'],book:[81,92],steps:[
    s('Два сеанса открыли транзакции и пока только читают. У них есть vxid, но XID может ещё не быть.','Two sessions begin transactions and only read. They have vxids, but may not yet have XIDs.',[a('sessionA','client','Сеанс A','Session A',['BEGIN first','vxid 4/12 · xid —']),a('sessionB','client','Сеанс B','Session B',['BEGIN later','vxid 9/6 · xid —'])],[],'BEGIN;\nSELECT pg_current_xact_id_if_assigned();','Виртуальный ID состоит из номера backend-процесса внутри сервера и локального счётчика, а не из PID ОС. Чтение без побочных записей обычно не требует обычного XID.','A virtual ID combines the backend’s server process number and a local counter, not its OS PID. Reading without write side effects normally needs no regular XID.'),
    s('B первым начинает запись и получает 600; A записывает позже и получает 601.','B writes first and receives 600; A writes later and receives 601.',[a('sessionA','client','Сеанс A','Session A',['first write → xid 601']),a('sessionB','client','Сеанс B','Session B',['first write → xid 600']),status('counter','Общий счётчик','Shared counter',['nextXid: 600 → 602'])],[f('sessionB','counter','assign 600','internal'),f('sessionA','counter','assign 601','internal')],'','Счётчик общий для всех баз одного кластера. Номера отражают порядок выделения XID, связанный с первой записью, а не порядок открытия транзакций.','The counter is shared across databases in one cluster. IDs reflect allocation order, associated with the first write, not the order transactions began.'),
    s('Транзакция 601 может зафиксироваться раньше, пока 600 всё ещё работает.','Transaction 601 may commit first while 600 is still running.',[a('finish','timeline','Порядок завершения','Completion order',[],{items:['allocate 600','allocate 601','COMMIT 601','600 still active']}),a('states','table','Статусы','Statuses',[],{columns:['xid','state'],rows:[[600,'in progress'],[601,'committed']]})],[],'','Большее число не означает более поздний COMMIT. Именно поэтому проверки видимости не могут свестись к сравнению xmin с одним номером текущего читателя.','A higher number does not imply a later COMMIT. Visibility therefore cannot be reduced to comparing xmin against the reader’s single transaction ID.'),
    s('В заголовке версии — 32-битный XID; полный xid8 дополнительно учитывает эпоху.','A tuple header has a 32-bit XID; full xid8 also includes an epoch.',[a('ids','table','Два представления','Two representations',[],{columns:['representation','example','width'],rows:[['tuple xmin','601','32 bits'],['xid8','epoch 2 | xid 601','64 bits']]}),status('counter','Текущее состояние выдачи','Live allocation state',['shared memory','next full XID'])],[f('counter','ids','assign ID','internal')],'SELECT pg_current_xact_id();','Полный идентификатор отделяет разные обороты 32-битного счётчика. SQL-функция возвращает xid8; это не означает, что каждое поле xmin в heap-строке стало 64-битным.','A full ID distinguishes different cycles of the 32-bit counter. The SQL function returns xid8; this does not make every heap tuple’s xmin field 64 bits.'),
    s('32-битное пространство циклично; специальные номера пропускаются при выдаче обычных XID.','The 32-bit ID space is circular; reserved IDs are skipped during ordinary allocation.',[a('cycle','ring','Круг XID','XID circle',[],{items:['3','…','2³¹','…','2³²−1','3 again']})],[],'','Сравнение возраста использует циклическую арифметику. Заморозка старых версий нужна даже при наличии xid8; подробный механизм появится после снимков и очистки.','Age comparisons use circular arithmetic. Old tuples still need freezing even though xid8 exists; we explain the mechanism after snapshots and cleanup.'),
    s('Даже запрос номера может выделить XID; вариант if_assigned этого не делает.','Even asking for an ID can allocate one; the if_assigned variant avoids doing so.',[a('calls','table','Два запроса','Two requests',[],{columns:['function','without assigned XID'],rows:[['..._if_assigned()','NULL'],['pg_current_xact_id()','assigns an XID']]}),versions([['tuple A',600,0,'value A'],['tuple B',601,0,'value B']])],[],'SELECT pg_current_xact_id_if_assigned();\nSELECT pg_current_xact_id();','Для вложенной транзакции эти функции возвращают номер верхнего уровня. Номер в заголовке конкретной версии при этом может быть subxid; к этому вернёмся через SAVEPOINT.','In a subtransaction, these functions return the top-level ID. A particular tuple header can instead contain a subxid; SAVEPOINT will make that distinction concrete.')
  ]}),
  c({number:16,id:'transaction-status',group:2,title:['Где хранится исход транзакции','Where a transaction’s outcome lives'],question:['У версии xmin=600. Как читатель выяснит, что сделала транзакция 600?','A tuple has xmin=600. How does a reader determine transaction 600’s outcome?'],next:['Одна транзакция может отменить только часть работы. Как это устроено?','A transaction can roll back only part of its work. How is that represented?'],docs:['transaction-id.html','storage-file-layout.html','functions-info.html','subxacts.html'],book:[85,86],steps:[
    s('Одного числа xmin=600 недостаточно: транзакция могла работать, завершиться или отмениться.','The number xmin=600 is insufficient: its transaction might be active, committed, or aborted.',[versions([['(0,1)',600,0,'order 17']]),status('question','Нужен исход','Outcome needed',['600: active?','600: committed?','600: aborted?'])],[f('heap','question','xmin = 600','internal')],'','Сравнение номеров решает только часть задачи. Изменения отменённой транзакции не становятся видимыми даже тогда, когда её номер очень маленький.','Comparing IDs solves only part of the problem. An aborted transaction’s changes do not become visible merely because its ID is small.'),
    s('ProcArray в общей памяти описывает активные сеансы и их транзакции.','ProcArray in shared memory describes active sessions and their transactions.',[versions([['(0,1)',600,0,'order 17']]),a('active','table','Активность в памяти','Activity in shared memory',[],{columns:['backend','xid','state'],rows:[['A',600,'active'],['B','—','read only']]})],[f('heap','active','is 600 active?','internal')],'','Для ещё работающей чужой транзакции вставка не считается зафиксированной. Эта текущая структура не является долговечным журналом всех прошлых завершений.','An insertion by another still-running transaction is not treated as committed. This live structure is not a permanent history of every past completion.'),
    s('pg_xact хранит компактные статусы по XID; доступ идёт через отдельный SLRU-кеш.','pg_xact stores compact statuses by XID, accessed through a separate SLRU cache.',[a('xact','table','Статусы pg_xact','pg_xact statuses',['2 bits / XID'],{columns:['xid','status'],rows:[[600,'in progress'],[601,'committed'],[602,'aborted']]}),status('slru','Кеш статусов','Status cache',['SLRU','not shared_buffers'])],[f('slru','xact','status page','internal')],'','pg_xact — специальные файлы, а не обычная SQL-таблица. Два бита кодируют четыре состояния, включая subcommitted; это не означает отдельную строку большого журнала на каждый COMMIT.','pg_xact contains special files, not an ordinary SQL table. Two bits encode four states, including subcommitted; there is no large SQL log row for each COMMIT.'),
    s('COMMIT меняет статус 600; ему не нужно обходить каждую созданную версию.','COMMIT changes status 600 without visiting every tuple it created.',[a('xact','table','Сохранённый исход','Recorded outcome',[],{columns:['xid','status'],rows:[[600,'committed'],[601,'committed'],[602,'aborted']]}),versions([['(0,1)',600,0,'order 17'],['(0,2)',600,0,'order 18']])],[f('xact','heap',b('Исход общий для версий','One outcome for tuples'),'internal')],'','Рисунок связывает общий исход с двумя версиями, но не изображает физический обход страниц при COMMIT. WAL обеспечивает надёжное восстановление этого исхода и связанных изменений.','The scene relates one outcome to two tuples; it does not depict COMMIT physically scanning their pages. WAL protects recovery of the outcome and related changes.'),
    s('Позднейшее чтение может записать в заголовок hint bit «xmin committed».','A later read may set an “xmin committed” hint bit in the tuple header.',[a('xact','table','Проверенный статус','Checked status',[],{columns:['xid','status'],rows:[[600,'committed']]}),versions([['(0,1)',600,0,'order 17']],['HEAP_XMIN_COMMITTED'])],[f('xact','heap','set hint bit','internal')],'','Hint bit экономит повторные проверки статуса и может сделать страницу грязной даже при SELECT. Он не отменяет сравнение с границами снимка: committed сейчас ещё не значит visible в старом снимке.','A hint bit saves repeated status checks and can dirty a page even during SELECT. It does not bypass snapshot bounds: committed now does not imply visible in an older snapshot.'),
    s('Статусы, родители вложенных транзакций и группы блокировок хранят разные сведения.','Statuses, subtransaction parents, and lock groups store different information.',[a('stores','table','Разные структуры','Different structures',[],{columns:['location','purpose'],rows:[['pg_xact','transaction outcome'],['pg_subtrans','subxid → parent xid'],['pg_multixact','lock group members'],['pg_commit_ts','optional commit time']]})],[],'SELECT pg_xact_status(pg_current_xact_id());','Время COMMIT при включённом track_commit_timestamp не заменяет снимок и не определяет MVCC-видимость. Старые статусы могут удаляться, когда они больше не нужны; приложение не получает вечную историю через pg_xact.','Commit timestamps, when enabled, do not replace snapshots or determine MVCC visibility. Old statuses can be discarded once unnecessary; pg_xact is not a permanent application history.')
  ]}),
  c({number:17,id:'savepoints',group:2,title:['Отменить часть работы','Roll back part of the work'],question:['Как сохранить первый INSERT, если следующий фрагмент работы нужно отменить?','How can the first INSERT survive while a later part is rolled back?'],next:['Статусы известны. Как запомнить, что было видно в момент начала чтения?','Outcomes are known. How can a reader remember what was visible when it started?'],docs:['tutorial-transactions.html','sql-savepoint.html','sql-rollback-to.html','subxacts.html'],book:[92,96],steps:[
    s('Верхняя транзакция 700 добавила заказ 20, но пока не фиксируется.','Top-level transaction 700 inserted order 20 but has not committed.',[backend(['top-level xid 700']),versions([['order 20',700,0,'Pen × 1']])],[f('db','heap','INSERT 20','internal')],"BEGIN;\nINSERT INTO orders (id, item, qty) VALUES (20, 'Pen', 1);",'Пример начинается с отсутствующих заказов 20–22. Их номера выбраны только для демонстрации; предыдущие заказы не меняются.','This example starts without orders 20–22. Their IDs are only teaching values; previously existing orders are unchanged.'),
    s('После SAVEPOINT новая запись получает subxid 701 с родителем 700.','After SAVEPOINT, a new write receives subxid 701 with parent 700.',[versions([['order 20',700,0,'Pen × 1'],['order 21',701,0,'Cup × 1']]),a('parents','tree','Вложенность','Subtransaction hierarchy',[],{nodes:[{id:'p',label:'700 · parent'},{id:'s',label:'701 · child'}],edges:[['p','s']]})],[f('parents','heap','child write','internal')],"SAVEPOINT optional_item;\nINSERT INTO orders (id, item, qty) VALUES (21, 'Cup', 1);",'Родитель всегда получает XID раньше дочерней пишущей транзакции. Связь subxid→parent хранится в pg_subtrans; SQL-функция текущего XID всё равно возвращает верхний 700.','A parent receives its XID before a writing child. pg_subtrans stores the subxid-to-parent link; the current-XID SQL function still returns top-level 700.'),
    s('ROLLBACK TO отменяет заказ 21, сохраняя более ранний заказ 20.','ROLLBACK TO cancels order 21 while preserving the earlier order 20.',[versions([['order 20',700,0,'own visible'],['order 21',701,0,'aborted bytes']]),status('child','Исход 701','Outcome of 701',['aborted'])],[f('child','heap','701 aborted','internal')],'ROLLBACK TO SAVEPOINT optional_item;','Откатывается работа после точки сохранения. Физические байты отменённой версии могут остаться, но в логическом результате родительской транзакции её больше нет.','Work after the savepoint is rolled back. The aborted tuple’s bytes may remain, but it is no longer part of the parent transaction’s logical result.'),
    s('Новая ветка 702 добавляет заказ 22. RELEASE не делает её независимо надёжной.','A new branch, 702, inserts order 22. RELEASE does not make it independently durable.',[versions([['order 20',700,0,'Pen × 1'],['order 21',701,0,'aborted'],['order 22',702,0,'Bag × 1']]),a('parents','tree','Зависимость от родителя','Dependence on the parent',[],{nodes:[{id:'p',label:'700 · still open'},{id:'s',label:'702 · subcommitted'}],edges:[['p','s']]})],[],"INSERT INTO orders (id, item, qty) VALUES (22, 'Bag', 1);\nRELEASE SAVEPOINT optional_item;",'Если родитель 700 теперь отменится, заказ 22 тоже не будет зафиксирован. Subcommitted означает зависимый промежуточный исход, а не самостоятельный COMMIT.','If parent 700 now aborts, order 22 will not commit either. Subcommitted is a dependent intermediate outcome, not an independent COMMIT.'),
    s('COMMIT родителя фиксирует 20 и 22; отменённый 21 не возвращается.','The parent COMMIT commits 20 and 22; aborted order 21 does not return.',[a('outcomes','table','Итоговые статусы','Final statuses',[],{columns:['xid','state'],rows:[[700,'committed'],[701,'aborted'],[702,'committed']]}),orders([[20,42,'Pen',1],[22,42,'Bag',1]])],[f('outcomes','orders',b('Новое чтение','Fresh read'),'internal')],'COMMIT;','Одна атомарная верхняя транзакция может содержать несколько зависимых XID. Поэтому функции проверки снимка, рассчитанные на top-level XID, нельзя бездумно применять к subxid.','One atomic top-level transaction can contain several dependent XIDs. Snapshot helper functions designed for top-level XIDs must not be applied blindly to subxids.')
  ]}),
  c({number:18,id:'snapshots',group:2,title:['Снимок — несколько чисел','A snapshot is a few numbers'],question:['Как сохранить прежний взгляд на данные, когда транзакции продолжают завершаться?','How can a reader retain its view while transactions keep completing?'],next:['Снимок 809:811:809 получен. Как он выбирает конкретную версию?','The snapshot 809:811:809 is captured. How does it choose a particular version?'],docs:['functions-info.html','transaction-iso.html','mvcc-intro.html'],book:[97,104],steps:[
    s('809 вставила Alice и ещё работает; 810 вставила Bob и уже зафиксировалась.','809 inserted Alice and is still active; 810 inserted Bob and has committed.',[a('activity','table','В момент чтения','At read start',[],{columns:['xid','change','state'],rows:[[809,'Alice = 1000','active'],[810,'Bob = 100','committed']]})],[],'','Транзакции завершились не в порядке номеров. По текущей активности и границам сервер строит снимок, который позволит позже восстановить именно этот взгляд.','Transactions did not complete in ID order. The server uses live activity and bounds to capture a snapshot that can retain this view later.'),
    s('Снимок сохраняет xmin=809, xmax=811 и активный список {809}.','The snapshot records xmin=809, xmax=811, and active list {809}.',[status('snapshot','Снимок читателя','Reader snapshot',['xmin = 809','xmax = 811','xip = {809}']),a('activity','timeline','Шкала XID','XID line',[],{items:['<809 · completed','809 · active','810 · committed','≥811 · not completed']})],[f('activity','snapshot','capture','internal')],'BEGIN ISOLATION LEVEL REPEATABLE READ;\nSELECT pg_current_snapshot();','xmax — единица после наибольшего завершившегося XID; это не обязательно следующий невыданный XID. Список xip содержит подходящие активные top-level XID ниже xmax.','xmax is one past the highest completed XID; it is not necessarily the next unassigned XID. xip holds the relevant in-progress top-level XIDs below xmax.'),
    s('809 теперь делает COMMIT, но сохранённый список {809} не меняется.','809 now commits, but the saved list {809} does not change.',[status('snapshot','Тот же снимок','The same snapshot',['809:811:809']),a('activity','table','Текущие исходы','Current outcomes',[],{columns:['xid','now'],rows:[[809,'committed'],[810,'committed']]})],[],'','Нынешний статус committed не доказывает, что транзакция была завершена при создании снимка. Запомненный xip сохраняет это различие без копирования всей таблицы.','A committed status now does not prove a transaction had completed when the snapshot was captured. The saved xip preserves that distinction without copying the whole table.'),
    s('811 после снимка меняет Bob со 100 на 200 и фиксируется.','After snapshot capture, 811 changes Bob from 100 to 200 and commits.',[versions([['Alice',809,0,'1000'],['Bob v1',810,811,'100'],['Bob v2',811,0,'200']]),status('snapshot','Старый снимок','Older snapshot',['xmin 809 · xmax 811','xip {809}'])],[],"-- Another session:\nBEGIN;\nUPDATE accounts SET balance = 200 WHERE id = 'Bob';\nCOMMIT;",'Для этого worked example отдельная accounts содержит Alice=1000 и Bob=100. Версия Bob v1 остаётся, потому что старому снимку нужна именно она; SQL использует текстовые ключи этой модели.','This worked example uses a separate accounts state with Alice=1000 and Bob=100. Bob v1 remains because the older snapshot needs it; the SQL uses this model’s text keys.'),
    s('Старый снимок возвращает Bob=100 и не возвращает Alice.','The older snapshot returns Bob=100 and does not return Alice.',[status('snapshot','Снимок 809:811:809','Snapshot 809:811:809',['809 was active','811 is too new']),accounts([['Bob',100]],[b('Результат этого снимка','This snapshot’s result')])],[f('snapshot','accounts','visibility rules','internal')],'SELECT id, balance FROM accounts ORDER BY id;','Alice исключается по активному 809 в снимке, хотя 809 уже завершилась. Новая Bob v2 исключается по 811; удаление Bob v1 транзакцией 811 также не видно, поэтому v1 остаётся результатом.','Alice is excluded because 809 was active in the snapshot, though it has since completed. Bob v2 is too new; 811’s deletion of Bob v1 is also invisible, so v1 remains the result.'),
    s('Новый снимок после обеих фиксаций уже может вернуть Alice=1000 и Bob=200.','A fresh snapshot after both commits can return Alice=1000 and Bob=200.',[status('snapshot','Новый снимок','Fresh snapshot',[b('809 и 811 завершены','809 and 811 completed')]),accounts([['Alice',1000],['Bob',200]])],[f('snapshot','accounts','fresh view','internal')],'COMMIT;\nSELECT id, balance FROM accounts ORDER BY id;','Это разные снимки одной физической таблицы, а не разные копии всех её строк. Теперь отдельно пройдём каждую проверку для старого снимка, чтобы результат перестал быть магией.','These are different snapshots over one physical table, not separate copies of all its rows. Next we trace each check in the older snapshot so its result is no longer magic.')
  ]}),
  c({number:19,id:'visibility',group:2,title:['Проверка видимости по шагам','Check visibility step by step'],question:['Какая версия проходит проверки снимка 809:811:809?','Which tuple passes snapshot 809:811:809?'],next:['Если снимок меняется между командами, что увидит приложение?','What does the app see when the snapshot changes between statements?'],docs:['functions-info.html','ddl-system-columns.html','transaction-iso.html'],book:[98,105],steps:[
    s('У снимка и у версии есть поля xmin/xmax, но они означают разные вещи.','Snapshots and tuples both have xmin/xmax fields, with different meanings.',[status('snapshot','Границы снимка','Snapshot bounds',['xmin = 809','xmax = 811','xip = {809}']),versions([['Alice',809,0,'1000'],['Bob v1',810,811,'100'],['Bob v2',811,0,'200']])],[],'','У снимка это границы пространства XID; у tuple это создавшая и удалившая/блокирующая транзакции. Дальше рассматриваем обычные committed/aborted версии без MultiXact и собственных изменений.','Snapshot fields are XID bounds; tuple fields identify creating and deleting/locking transactions. We first consider ordinary committed/aborted tuples without MultiXacts or own changes.'),
    s('Alice имеет xmin=809: этот XID был активен в снимке, поэтому вставка не видна.','Alice has xmin=809: that XID was active in the snapshot, so the insertion is invisible.',[status('snapshot','Снимок','Snapshot',['xip = {809}']),versions([['Alice',809,0,'1000']]),status('decision','Решение','Decision',['creator 809 ∈ xip','not visible'])],[f('heap','snapshot','test creator 809','internal'),f('snapshot','decision','in progress at capture','internal')],'','Даже hint bit committed у Alice не изменил бы ответ старого снимка. Бит сообщает итог транзакции, а xip сообщает её состояние в нужный момент.','Even a committed hint bit on Alice would not change this old snapshot’s answer. The hint tells the transaction’s outcome; xip preserves its state at capture time.'),
    s('Создатель Bob v1 — 810: он ниже xmax, отсутствует в xip и зафиксирован.','Bob v1’s creator, 810, is below xmax, absent from xip, and committed.',[status('snapshot','Снимок','Snapshot',['809 ≤ 810 < 811','810 ∉ xip']),versions([['Bob v1',810,811,'100']]),status('decision','Первая проверка','First check',['creator committed','insertion visible ✓'])],[f('heap','snapshot','test xmin 810','internal'),f('snapshot','decision','creator visible','internal')],'','Отсутствие XID в xip означает, что он завершился к снимку, но не отличает COMMIT от ROLLBACK. Проверка committed здесь обязательна.','Absence from xip means the XID completed before the snapshot, but does not distinguish COMMIT from ROLLBACK. The committed-status check is necessary.'),
    s('Удаляющий XID 811 не виден снимку, поэтому Bob v1 ещё не считается удалённой.','Deleting XID 811 is invisible to the snapshot, so Bob v1 is not yet considered deleted.',[status('snapshot','Снимок','Snapshot',['xmax = 811','811 ≥ snapshot xmax']),versions([['Bob v1',810,811,'100']]),status('decision','Версия подходит','Tuple qualifies',['insert visible ✓','delete visible ✕','return 100'])],[f('heap','snapshot','test tuple xmax 811','internal'),f('snapshot','decision','keep old version','internal')],'','Для видимости обычной версии нужны видимая вставка и невидимое удаление. Это объясняет, почему старый запрос возвращает 100 уже после чужого UPDATE и COMMIT.','An ordinary visible tuple needs a visible insertion and an invisible deletion. This explains why the older query returns 100 even after another session’s UPDATE and COMMIT.'),
    s('Создатель Bob v2 — 811: он на верхней границе, поэтому новая версия исключается.','Bob v2’s creator is 811, at the upper bound, so the new tuple is excluded.',[status('snapshot','Снимок','Snapshot',['xmax = 811']),versions([['Bob v2',811,0,'200']]),status('decision','Новая версия','New tuple',['811 ≥ 811','not visible'])],[f('heap','snapshot','test xmin 811','internal'),f('snapshot','decision','too new','internal')],'','Нулевой xmax говорит, что версия не помечена удалённой в этом простом случае. Он не делает её вставку видимой автоматически: сначала нужно пройти проверку xmin.','Zero xmax means no deletion is marked in this simple case. It does not automatically make the insertion visible; xmin must pass its checks first.'),
    s('Даже XID 808 ниже xmin не помогает версии, если 808 была отменена.','Even XID 808 below xmin cannot make a tuple visible if 808 aborted.',[status('snapshot','Снимок','Snapshot',['xmin = 809']),versions([['aborted row',808,0,'never visible']]),status('decision','Проверка статуса','Status check',['808 < 809','808 aborted → reject'])],[f('heap','decision','check commit status','internal')],'','Правило «всё ниже xmin видно» неполно: ниже границы находятся завершённые транзакции, а их изменения бывают committed или aborted. В результат включаются только зафиксированные вставки.','“Everything below xmin is visible” is incomplete: transactions below that boundary have completed, but their changes may be committed or aborted. Only committed insertions qualify.'),
    s('Для своих изменений дополнительно важен номер команды: старый курсор не видит последующие вставки.','Own changes also need command IDs: an older cursor does not see later insertions.',[a('commands','timeline','Команды одного XID','Commands in one XID',[],{items:['INSERT 87 · earlier','DECLARE cursor','INSERT 88 · later','FETCH → includes 87 only']}),a('own','table','Собственные версии','Own tuples',[],{columns:['id','command','cursor view'],rows:[[87,'before cursor','visible'],[88,'after cursor','not visible']]})],[f('commands','own','command boundary','internal')],"BEGIN;\nINSERT INTO orders (id,item,qty) VALUES (87,'Pen',1);\nDECLARE order_cursor CURSOR FOR SELECT id FROM orders WHERE id IN (87,88);\nINSERT INTO orders (id,item,qty) VALUES (88,'Cup',1);\nFETCH ALL FROM order_cursor;\nROLLBACK;",'cmin/cmax описывают команды внутри транзакции. Собственные предыдущие записи обычно видны, но снимок выполнения курсора не должен включать изменения, сделанные позже; одного совпадения XID недостаточно.','cmin/cmax describe commands within a transaction. Earlier own writes are normally visible, but a cursor’s execution snapshot must exclude later changes; matching the transaction ID alone is insufficient.')
  ]}),
  c({number:20,id:'read-committed',group:2,title:['Новый снимок для новой команды','A new snapshot for each statement'],question:['Почему два SELECT внутри одного BEGIN могут вернуть разные значения?','Why can two SELECTs inside one BEGIN return different values?'],next:['Читатели получают свежие данные. Как не потерять изменения двух писателей?','Readers obtain fresh data. How can two writers avoid losing a change?'],docs:['transaction-iso.html','sql-set-transaction.html'],book:[55,63],steps:[
    s('При Read Committed первый SELECT берёт снимок S1 и видит баланс 100.','At Read Committed, the first SELECT takes snapshot S1 and sees balance 100.',[a('reader','client','Читатель R','Reader R',['BEGIN','S1 → balance 100']),accounts([['A',100]])],[f('reader','accounts','SELECT · S1','request')],"BEGIN ISOLATION LEVEL READ COMMITTED;\nSELECT balance FROM accounts WHERE id = 'A';",'Новый независимый пример начинается с A=100. Read Committed — обычный уровень по умолчанию; снимок фиксируется на начало команды, а не на весь BEGIN.','This independent example starts at A=100. Read Committed is the normal default level; its snapshot is fixed for a statement, not for the entire BEGIN.'),
    s('Параллельная T811 готовит баланс 120, пока первая команда читателя ещё использует S1.','Concurrent T811 prepares balance 120 while the reader’s first statement still uses S1.',[a('writer','client','Писатель W','Writer W',['T811 · open']),versions([['A v1',810,811,'100'],['A v2',811,0,'120']]),a('reader','client','Читатель R','Reader R',['S1 stays fixed'])],[f('writer','heap','UPDATE','internal')],"-- Session W:\nBEGIN;\nUPDATE accounts SET balance = 120 WHERE id = 'A';",'Долгая обычная команда чтения не меняет снимок посередине из-за чужих обновлений. Эта сценка растягивает её выполнение для наблюдения, не задавая реальное время планировщика.','A long ordinary read statement does not replace its snapshot midway because another session updates data. The animation stretches execution for observation, without prescribing real scheduler timing.'),
    s('Даже если W уже зафиксировалась, продолжающийся SELECT по S1 возвращает 100.','Even after W commits, the still-running SELECT on S1 returns 100.',[a('writer','client','Писатель W','Writer W',['COMMIT ✓']),a('reader','client','Первая команда R','R’s first statement',['S1 → 100']),versions([['A v1',810,811,'100'],['A v2',811,0,'120']])],[f('heap','reader','S1: old version','reply')],'-- Session W:\nCOMMIT;','Согласованность обычного SELECT относится к его снимку. Read Committed не обещает постоянно обновляющуюся картинку во время одной команды.','An ordinary SELECT is consistent with its statement snapshot. Read Committed does not promise a continuously refreshing view within one statement.'),
    s('Следующий SELECT того же R создаёт S2 и уже возвращает 120.','R’s next SELECT takes S2 and now returns 120.',[a('reader','client','Вторая команда R','R’s second statement',['same BEGIN','new S2 → 120']),accounts([['A',120]])],[f('reader','accounts','SELECT · S2','request'),f('accounts','reader','120','reply')],"-- Session R:\nSELECT balance FROM accounts WHERE id = 'A';",'Между двумя командами появилась чужая фиксация, поэтому снимки различаются. Это разрешённое неповторяющееся чтение, а не неисправность кеша.','Another transaction committed between the statements, so their snapshots differ. This is permitted nonrepeatable reading, not a cache malfunction.'),
    s('R добавляет 5 и видит собственное незафиксированное значение 125.','R adds 5 and sees its own uncommitted value 125.',[a('reader','client','Свои изменения R','R’s own changes',['UPDATE +5','own SELECT → 125']),accounts([['A',125]],[b('Внутри R','Inside R')])],[f('reader','accounts','120 + 5','internal')],"UPDATE accounts SET balance = balance + 5 WHERE id = 'A';\nSELECT balance FROM accounts WHERE id = 'A';",'Правило видимости собственных предыдущих команд действует и здесь. Другим сеансам это значение становится доступно после COMMIT и при подходящем новом снимке.','The rule for seeing earlier own commands still applies. Other sessions can see the value after COMMIT with an appropriate new snapshot.'),
    s('После COMMIT результат R — 125. Но свежий снимок сам по себе не защищает расчёт в приложении.','After COMMIT, R’s result is 125. A fresh snapshot alone does not protect app-side arithmetic.',[accounts([['A',125]]),a('reader','client','R завершилась','R completed',['COMMIT ✓'])],[f('reader','accounts','commit','internal')],'COMMIT;','Если приложение читает число, вычисляет новое у себя и позже записывает константу, другое изменение может затереться. Для этого следующему примеру нужны два писателя.','If the app reads a value, computes a replacement locally, and later writes a constant, another change can be overwritten. The next example needs two writers to expose this.')
  ]}),
  c({number:21,id:'concurrent-updates',group:2,title:['Два списания с одного счёта','Two debits from one account'],question:['Почему чтение 100 и последующая запись константы могут потерять чужое списание?','Why can reading 100 and later writing a constant lose another debit?'],next:['Арифметическое UPDATE ждёт другого писателя. Что именно его удерживает?','The arithmetic UPDATE waits for another writer. What holds it up?'],docs:['transaction-iso.html','explicit-locking.html'],book:[55,63],steps:[
    s('A и B прочитали 100. A хочет списать 20, B — 30.','A and B both read 100. A wants to debit 20, B wants to debit 30.',[accounts([['A',100]]),a('writerA','client','Писатель A','Writer A',['read 100','local result = 80']),a('writerB','client','Писатель B','Writer B',['read 100','local result = 70'])],[f('accounts','writerA','100','reply'),f('accounts','writerB','100','reply')],"SELECT balance FROM accounts WHERE id = 'A';",'Это новая ветка от баланса 100. Если оба списания сохранятся, правильный итог — 50. Пока приложения вычислили две независимые константы по одному старому значению.','This is a new branch starting from balance 100. If both debits are preserved, the correct result is 50. The apps have instead computed two constants from the same old value.'),
    s('A записывает константу 80 и фиксируется.','A writes the constant 80 and commits.',[a('writerA','client','Писатель A','Writer A',['SET balance = 80']),accounts([['A',80]]),a('writerB','client','Писатель B','Writer B',['still plans 70'])],[f('writerA','accounts','80','internal')],"UPDATE accounts SET balance = 80 WHERE id = 'A';",'Показываем отдельную успешно зафиксированную команду A. B всё ещё хранит своё вычисленное число 70; новый снимок при UPDATE не заставит клиент пересчитать эту константу.','A’s standalone command commits successfully. B still holds its computed 70; a fresh UPDATE snapshot does not make the client recompute that constant.'),
    s('B записывает 70. Списание A потерялось: итог 70 вместо 50.','B writes 70. A’s debit is lost: the result is 70 instead of 50.',[a('writerB','client','Писатель B','Writer B',['SET balance = 70']),accounts([['A',70]],['expected: 50'])],[f('writerB','accounts','overwrite 80 → 70','internal')],"UPDATE accounts SET balance = 70 WHERE id = 'A';",'Обе команды законны по отдельности. Ошибка — в разделении бизнес-операции на чтение, локальную арифметику и слепую запись нового значения.','Both commands are individually legal. The mistake is splitting the business operation into a read, local arithmetic, and a blind replacement write.'),
    s('Повторим от 100: теперь A выполняет balance−20, а B — balance−30 прямо в SQL.','Restart from 100: A now uses balance−20 and B balance−30 directly in SQL.',[a('writerA','client','Писатель A','Writer A',['UPDATE balance - 20','holds row']),accounts([['A',80]],[b('Изменение A ещё открыто','A’s change still open')]),a('writerB','client','Писатель B','Writer B',['UPDATE balance - 30','waiting'])],[f('writerA','accounts','100 → 80','internal'),f('writerB','writerA','wait for transaction','wait')],"-- Session A, starting again at balance=100:\nBEGIN;\nUPDATE accounts SET balance = balance - 20 WHERE id = 'A';\n-- Session B:\nUPDATE accounts SET balance = balance - 30 WHERE id = 'A';",'Это альтернативный корректный путь на Read Committed. B находит целевую строку, но не может одновременно изменить её в конфликтующем режиме.','This is an alternative correct path at Read Committed. B finds the target row but cannot modify it concurrently in a conflicting mode.'),
    s('После COMMIT A команда B использует обновлённые 80 и получает 50.','After A commits, B uses the updated 80 and computes 50.',[a('writerA','client','Писатель A','Writer A',['COMMIT ✓']),a('writerB','client','Писатель B','Writer B',['80 - 30 = 50']),accounts([['A',50]])],[f('writerA','writerB','row available','reply'),f('writerB','accounts','80 → 50','internal')],'-- Session A:\nCOMMIT;','После ожидания Read Committed повторно проверяет условие WHERE на обновлённой версии. Строка всё ещё имеет id=A, поэтому выражение balance−30 применяется к её актуальному значению.','After waiting, Read Committed rechecks WHERE against the updated version. The row still has id=A, so balance−30 is applied to its current value.'),
    s('Оба списания сохранились: 100−20−30=50. Это координация записей одной строки.','Both debits survive: 100−20−30=50. This coordinates writes to one row.',[accounts([['A',50]],['100 - 20 - 30 = 50']),status('result','Результат','Result',[b('Нет потерянного списания','No debit lost')])],[],"SELECT balance FROM accounts WHERE id = 'A';",'В этой ветке B была отдельной командой и завершила свою неявную транзакцию. Для правил, охватывающих несколько строк, потребуется дополнительное рассуждение; сначала откроем механизм ожидания.','B was a standalone command in this branch and completed its implicit transaction. Rules spanning several rows need further reasoning; first we open the waiting mechanism.')
  ]}),
  c({number:22,id:'row-locks',group:2,title:['Кто удерживает строку','Who holds the row'],question:['Как один писатель заставляет другого дождаться завершения?','How does one writer make another wait for completion?'],next:['Ожидание защищает запись. А как удержать один снимок для нескольких чтений?','Waiting coordinates writes. How can several reads retain one snapshot?'],docs:['explicit-locking.html','xact-locking.html','view-pg-locks.html'],book:[268,272],steps:[
    s('A блокирует заказ 17 через SELECT FOR UPDATE, не меняя qty=2.','A locks order 17 with SELECT FOR UPDATE without changing qty=2.',[a('locker','client','Владелец A','Holder A',['T900 · FOR UPDATE']),versions([['order 17',850,900,'qty 2']],['xmax: lock-only'])],[f('locker','heap','row lock','internal')],"BEGIN;\nSELECT * FROM orders WHERE id = 17 FOR UPDATE;",'Служебные биты отличают блокировку от удаления. Поэтому ненулевой xmax не означает, что строка исчезла; SELECT FOR UPDATE сам может изменить страницу служебными сведениями.','Header bits distinguish locking from deletion. A nonzero xmax therefore does not mean the row disappeared; SELECT FOR UPDATE can itself change the page’s lock metadata.'),
    s('B хочет изменить ту же строку и ждёт окончания T900.','B wants to change the same row and waits for T900 to end.',[a('locker','client','Владелец A','Holder A',['T900 · open']),a('waiter','client','Писатель B','Writer B',['UPDATE qty = 3','waiting']),versions([['order 17',850,900,'qty 2']],['lock-only'])],[f('waiter','locker','wait on T900','wait')],"-- Session B:\nUPDATE orders SET qty = 3 WHERE id = 17;",'Конфликтующая блокировка не даёт двум писателям одновременно владеть одной строкой. Видимое ожидание часто связано с transactionid блокирующей транзакции, а не полным списком row locks в pg_locks.','Conflicting row locks prevent two writers from owning the same row concurrently. The observable wait often concerns the holder’s transactionid, rather than a complete row-lock inventory in pg_locks.'),
    s('Обычный SELECT C продолжает читать qty=2: row lock не блокирует такое чтение.','C’s ordinary SELECT still reads qty=2: the row lock does not block this read.',[a('locker','client','Владелец A','Holder A',['FOR UPDATE']),versions([['order 17',850,900,'qty 2']]),a('reader','client','Читатель C','Reader C',['SELECT → qty 2'])],[f('heap','reader','visible tuple','reply')],"-- Session C:\nSELECT qty FROM orders WHERE id = 17;",'Это свойство блокировки строки, а не обещание отсутствия любых ожиданий. Например, ACCESS EXCLUSIVE на таблице способен остановить обычный SELECT.','This is a property of row locks, not a promise that reads never wait. For example, an ACCESS EXCLUSIVE table lock can block an ordinary SELECT.'),
    s('У блокировок строк четыре режима с разной совместимостью.','Row locks have four modes with different compatibility.',[a('modes','table','Режимы строк','Row-lock modes',[],{columns:['mode','examples of conflict'],rows:[['KEY SHARE','UPDATE'],['SHARE','NO KEY UPDATE / UPDATE'],['NO KEY UPDATE','SHARE / same / UPDATE'],['UPDATE','all other row locks']]})],[],'','KEY SHARE позволяет менять неключевые поля и нужен, например, для защиты ссылочной целостности. Названия row-lock режимов не совпадают с похожими названиями table locks.','KEY SHARE permits nonkey updates and helps protect referential integrity. Row-lock mode names should not be confused with similarly named table-lock modes.'),
    s('A фиксируется; B получает доступ, создаёт qty=3 и завершает свою команду.','A commits; B gains access, creates qty=3, and finishes its statement.',[a('locker','client','A завершилась','A completed',['COMMIT ✓']),a('waiter','client','B продолжает','B resumes',['qty 2 → 3']),versions([['old version',850,901,'qty 2'],['new version',901,0,'qty 3']])],[f('locker','waiter','lock released','reply'),f('waiter','heap','UPDATE','internal')],'-- Session A:\nCOMMIT;','Блокировки обычно удерживаются до конца транзакции. Здесь B исполняет отдельный UPDATE, поэтому после возобновления и успеха завершает собственную неявную транзакцию.','Locks are normally held until transaction end. Here B runs a standalone UPDATE, so after resuming successfully it completes its own implicit transaction.'),
    s('NOWAIT позволяет получить ошибку сразу, если строка уже занята.','NOWAIT returns an error immediately if the row is already locked.',[a('locker','client','Другой владелец','Another holder',['FOR UPDATE']),a('waiter','client','Запрос NOWAIT','NOWAIT request',['lock not available','no waiting queue']),backend()],[f('waiter','db','try lock','request'),f('db','waiter','ERROR 55P03','reply')],"SELECT * FROM orders WHERE id = 17 FOR UPDATE NOWAIT;",'Это отдельная ветка с вновь занятой строкой. NOWAIT меняет поведение ожидания row lock, а не усиливает изоляцию снимка. Для стабильного чтения нескольких команд нужен другой уровень изоляции.','This is an alternative branch with the row locked again. NOWAIT changes row-lock waiting behavior, not snapshot isolation. Stable reads across statements need another isolation level.')
  ]}),
  c({number:23,id:'repeatable-read',group:2,title:['Один снимок на транзакцию','One snapshot for the transaction'],question:['Как повторно читать тот же баланс, пока другой сеанс его меняет?','How can repeated reads see the same balance while another session changes it?'],next:['Стабильный снимок — уже защита любого бизнес-условия?','Does a stable snapshot protect every business rule?'],docs:['transaction-iso.html','sql-set-transaction.html'],book:[63,70],steps:[
    s('Repeatable Read берёт снимок S при первом обычном операторе, а не просто на BEGIN.','Repeatable Read takes snapshot S at the first ordinary statement, not merely at BEGIN.',[a('reader','client','Транзакция R','Transaction R',['BEGIN RR','first SELECT → S']),accounts([['A',100]])],[f('reader','accounts','SELECT · snapshot S','request')],"BEGIN ISOLATION LEVEL REPEATABLE READ;\nSELECT balance FROM accounts WHERE id = 'A';",'В новом примере исходно A=100. Точнее, снимок задаётся первым оператором, не относящимся к управлению транзакцией; следующие команды используют ту же границу.','This new example starts at A=100. More precisely, the first non-transaction-control statement establishes the snapshot; later statements use the same boundary.'),
    s('W меняет 100 на 120 и фиксируется, пока R остаётся открытой.','W changes 100 to 120 and commits while R stays open.',[a('writer','client','Писатель W','Writer W',['UPDATE → 120','COMMIT ✓']),versions([['A v1',810,811,'100'],['A v2',811,0,'120']]),a('reader','client','Читатель R','Reader R',['holds snapshot S'])],[f('writer','heap','update + commit','internal')],"-- Session W:\nUPDATE accounts SET balance = 120 WHERE id = 'A';",'Чужая фиксация не заменяет сохранённый снимок R. Старая версия остаётся нужна читающей транзакции и потому пока не подлежит удалению.','The other commit does not replace R’s saved snapshot. R still needs the old tuple, so it cannot yet be removed.'),
    s('Второй SELECT R снова возвращает 100. Фантомные чтения тоже исключены.','R’s second SELECT again returns 100. Phantom reads are prevented as well.',[a('reader','client','Второе чтение R','R’s second read',['same S → 100']),accounts([['A',100]],[b('Взгляд R','R’s view')])],[f('accounts','reader','100','reply')],"-- Session R:\nSELECT balance FROM accounts WHERE id = 'A';",'В PostgreSQL Repeatable Read сильнее минимального стандартного определения: повторный запрос с тем же условием не добавляет чужие поздние вставки. Но сериализационные аномалии ещё возможны.','PostgreSQL Repeatable Read is stronger than the minimum SQL-standard definition: a repeated predicate query does not acquire later concurrent inserts. Serialization anomalies remain possible.'),
    s('Попытка R обновить изменённую W строку завершается serialization failure.','R’s attempt to update the row changed by W fails with a serialization error.',[a('reader','client','Обновление R','R’s update',['UPDATE balance + 5']),versions([['A v1',810,811,'snapshot value 100'],['A v2',811,0,'committed 120']]),status('error','Результат','Result',['SQLSTATE 40001','concurrent update'])],[f('reader','heap','try UPDATE','request'),f('heap','error','changed after S','reply')],"UPDATE accounts SET balance = balance + 5 WHERE id = 'A';",'R не может незаметно перейти к версии 120, которая не входит в её стабильный снимок. Это отличается от поведения Read Committed после ожидания; транзакцию требуется повторить целиком.','R cannot silently switch to version 120 outside its stable snapshot. This differs from Read Committed after waiting; the whole transaction must be retried.'),
    s('После ROLLBACK новая транзакция получает новый снимок и видит 120.','After ROLLBACK, a new transaction takes a new snapshot and sees 120.',[a('reader','client','Повтор всей R','Retry all of R',['ROLLBACK','new BEGIN RR']),accounts([['A',120]])],[f('reader','accounts','new snapshot','request'),f('accounts','reader','120','reply')],"ROLLBACK;\nBEGIN ISOLATION LEVEL REPEATABLE READ;\nSELECT balance FROM accounts WHERE id = 'A';",'Повторяют все решения, основанные на прежнем чтении, а не только последнюю упавшую команду. Новый снимок даёт входные данные для нового расчёта.','Retry all decisions based on the old read, not just the final failed command. A new snapshot provides inputs for a new calculation.'),
    s('Теперь R успешно добавляет 5 к 120 и фиксирует 125.','R can now add 5 to 120 and commit 125.',[a('reader','client','Новый запуск R','R’s new run',['120 + 5 = 125','COMMIT ✓']),accounts([['A',125]])],[f('reader','accounts','UPDATE + COMMIT','internal')],"UPDATE accounts SET balance = balance + 5 WHERE id = 'A';\nCOMMIT;",'При отсутствии нового конфликта повтор завершается. Стабильность чтений не доказывает корректность правил между разными строками: следующий пример меняет разные строки и потому требует SSI.','Without another conflict, the retry succeeds. Stable reads do not prove rules across different rows; the next example changes different rows and needs SSI.')
  ]}),
  c({number:24,id:'serializable',group:2,title:['Снимок плюс контроль зависимостей','A snapshot plus dependency checks'],question:['Как сохранить условие «хотя бы один дежурный», если меняются разные строки?','How can “at least one person on call” survive changes to different rows?'],next:['Одни прерывания вызваны зависимостями, другие — циклом ожиданий. Как их различить?','Some aborts arise from dependencies, others from wait cycles. How do they differ?'],docs:['transaction-iso.html','mvcc-serialization-failure-handling.html'],book:[70,74],steps:[
    s('Alice и Bob дежурят. Правило приложения: хотя бы один должен остаться.','Alice and Bob are on call. The app requires at least one to remain.',[a('roster','table','Дежурство','On-call roster',[],{columns:['person','active'],rows:[['Alice',true],['Bob',true]]}),status('rule','Общее условие','Shared invariant',['count(active) ≥ 1'])],[],"CREATE TABLE on_call (person text PRIMARY KEY, active boolean NOT NULL);\nINSERT INTO on_call VALUES ('Alice', true), ('Bob', true);",'Это условие относится к набору строк. Каждая отдельная строка может оставаться корректной по своим типам и ограничениям, даже когда совместный результат нарушает правило.','This invariant concerns a set of rows. Every individual row can satisfy its types and constraints while the combined result violates the rule.'),
    s('Две транзакции одновременно читают count=2 и решают, что могут снять своё дежурство.','Two concurrent transactions each read count=2 and decide they can go off call.',[a('roster','table','Один начальный набор','One initial state',[],{columns:['person','active'],rows:[['Alice',true],['Bob',true]]}),a('alice','client','Транзакция Alice','Alice transaction',['read count = 2','plans Alice = false']),a('bob','client','Транзакция Bob','Bob transaction',['read count = 2','plans Bob = false'])],[f('roster','alice','2','reply'),f('roster','bob','2','reply')],'SELECT count(*) FROM on_call WHERE active;','Обе транзакции читают собственный стабильный снимок до чужого изменения. По отдельности каждая решила бы правильно: оставить второго человека дежурить.','Each transaction reads a stable snapshot before the other change. Either decision would be correct by itself: leave the other person on call.'),
    s('Они меняют разные строки, поэтому обычного конфликта записи одной строки нет.','They update different rows, so there is no ordinary same-row write conflict.',[a('alice','client','Транзакция Alice','Alice transaction',['Alice = false','still sees Bob = true']),a('bob','client','Транзакция Bob','Bob transaction',['Bob = false','still sees Alice = true']),a('roster','table','Две подготовленные записи','Two prepared writes',[],{columns:['writer','row','new value'],rows:[['Alice tx','Alice',false],['Bob tx','Bob',false]]})],[f('alice','roster','UPDATE Alice','internal'),f('bob','roster','UPDATE Bob','internal')],"-- Alice transaction:\nUPDATE on_call SET active = false WHERE person = 'Alice';\n-- Bob transaction:\nUPDATE on_call SET active = false WHERE person = 'Bob';",'Внутри каждого снимка собственная запись видна, чужая — ещё нет. Блокировка только изменяемой строки не связывает два решения об общем count.','Each snapshot sees its own write but not the other write. Locking only the changed row does not connect the two decisions based on the shared count.'),
    s('При Repeatable Read обе фиксации возможны: получается ноль дежурных.','At Repeatable Read, both may commit, leaving nobody on call.',[a('roster','table','Возможный итог RR','Possible RR result',[],{columns:['person','active'],rows:[['Alice',false],['Bob',false]]}),status('rule','Нарушенное условие','Broken invariant',['count(active) = 0'])],[],'','Это write skew: стабильные снимки не обеспечили результат, эквивалентный последовательному исполнению. При последовательном запуске второй человек увидел бы count=1 и остался.','This is write skew: stable snapshots did not produce an outcome equivalent to serial execution. In a serial run, the second person would see count=1 and remain on call.'),
    s('При Serializable SSI обнаруживает опасные зависимости и прерывает одну транзакцию.','At Serializable, SSI detects dangerous dependencies and aborts one transaction.',[a('dependencies','plan','Зависимости чтение–запись','Read–write dependencies',[],{nodes:[{id:'alice',label:'Alice tx: read Bob'},{id:'bob',label:'Bob tx: read Alice'}],edges:[['alice','bob'],['bob','alice']]}),status('abort','Один возможный исход','One possible outcome',['Alice commits','Bob: SQLSTATE 40001'])],[f('dependencies','abort','SSI checks','internal')],'-- Repeat the scenario in both sessions with:\nBEGIN ISOLATION LEVEL SERIALIZABLE;','Повторяем сценарий от двух активных дежурных. Показан один возможный выбор жертвы; он не гарантирован. SIReadLock отмечают зависимости и сами не заставляют писателя ждать, как FOR UPDATE.','Repeat the scenario from two active people. This is one possible victim choice, not a guarantee. SIReadLocks track dependencies; they do not themselves make writers wait like FOR UPDATE.'),
    s('Bob повторяет всю транзакцию, видит одного дежурного и сохраняет своё дежурство.','Bob retries the whole transaction, sees one person on call, and stays on call.',[a('bob','client','Повтор Bob','Bob retry',['new snapshot','count = 1 → stay']),a('roster','table','Корректный итог','Valid result',[],{columns:['person','active'],rows:[['Alice',false],['Bob',true]]})],[f('roster','bob','count = 1','reply')],'ROLLBACK;\nBEGIN ISOLATION LEVEL SERIALIZABLE;\nSELECT count(*) FROM on_call WHERE active;\n-- Application keeps Bob active when count = 1.\nCOMMIT;','Повтор включает прежние чтения и бизнес-решение, а не только COMMIT. Serializable гарантирует сериализуемость успешно завершившихся транзакций; приложение должно корректно обрабатывать SQLSTATE 40001.','The retry includes previous reads and the business decision, not just COMMIT. Serializable guarantees serializable outcomes for successfully committed transactions; the app must handle SQLSTATE 40001 correctly.')
  ]})
];

// Data structures supply a backend; only that backend sends protocol replies.
// Keep this explicit when a scene zooms between the physical data and a client.
for (const chapter of chapters) {
  for (const stop of chapter.steps) {
    const actors = stop.diagram.actors;
    const actorByKey = new Map(actors.map(actor => [actor.key, actor]));
    const needsBackend = stop.diagram.flows.some(flow =>
      (flow.role === 'reply' && actorByKey.get(flow.to)?.kind === 'client' && !['client','server'].includes(actorByKey.get(flow.from)?.kind)) ||
      (flow.role === 'request' && actorByKey.get(flow.from)?.kind === 'client' && actorByKey.get(flow.to)?.kind !== 'server')
    );
    if (needsBackend && !actorByKey.has('db')) {
      if (actors.length >= 4) throw new Error(`No room for the backend in ${chapter.id}`);
      const server = backend();
      actors.push(server);
      actorByKey.set(server.key, server);
    }
    stop.diagram.flows = stop.diagram.flows.flatMap(flow => {
      const from = actorByKey.get(flow.from), to = actorByKey.get(flow.to);
      if (flow.role === 'reply' && from?.kind === 'client' && to?.kind === 'client') {
        return [{...flow, role:'internal'}]; // Coordination, not a wire reply.
      }
      if (flow.role === 'reply' && to?.kind === 'client' && from?.kind !== 'server') {
        return [{...flow,to:'db',role:'internal'}, {...flow,from:'db'}];
      }
      if (flow.role === 'request' && from?.kind === 'client' && to?.kind !== 'server') {
        return [{...flow,to:'db'}, {...flow,from:'db',role:'internal'}];
      }
      return [flow];
    });
  }
}
